def _shop_language_code(value):
    value = str(value or "en").strip().lower()
    aliases = {"english": "en", "shona": "sn", "ndebele": "nd", "isindebele": "nd"}
    value = aliases.get(value, value)
    return value if value in SHOP_LANGUAGE_NAMES else "en"


def _shop_translate_text(text, language):
    language = _shop_language_code(language)
    for source, translated in sorted(SHOP_TRANSLATIONS.get(language, {}).items(),
                                     key=lambda item: len(item[0]), reverse=True):
        text = text.replace(source, translated)
    return text


def _shop_translate_option(label, language):
    language = _shop_language_code(language)
    if language == "en":
        return label
    translated = SHOP_OPTION_TRANSLATIONS.get(language, {}).get(label)
    if translated is not None:
        return translated
    if label.startswith("View Cart ("):
        count, _, _items = label[len("View Cart ("):-1].partition(" ")
        noun = ("chinhu" if count == "1" else "zvinhu") if language == "sn" else "into"
        return f"{SHOP_OPTION_TRANSLATIONS[language]['View Cart']} ({count} {noun})"
    prefixes = {
        "sn": {
            "Change quantity — ": "Chinja huwandu — ",
            "Qty — ": "Huwandu — ",
            "Remove — ": "Bvisa — ",
            "Cancel ": "Bvisa ",
        },
        "nd": {
            "Change quantity — ": "Ntshintsha inani — ",
            "Qty — ": "Inani — ",
            "Remove — ": "Khupha — ",
            "Cancel ": "Khansela ",
        },
    }
    for source, target in prefixes.get(language, {}).items():
        if label.startswith(source):
            return target + label[len(source):]
    return _shop_translate_text(label, language)


def _shop_translate_messages(messages, language, preserve=()):
    language = _shop_language_code(language)
    if language == "en":
        return messages
    protected = sorted({str(value) for value in preserve
                        if value is not None and str(value).strip() and not str(value).isdigit()},
                       key=len, reverse=True)
    translated_messages = []
    for message in messages:
        translated = dict(message)
        text = translated.get("text")
        tokens = []
        if text:
            for index, value in enumerate(protected):
                token = f"__SHOP_VALUE_{index}__"
                if value in text:
                    text = text.replace(value, token)
                    tokens.append((token, value))
            text = _shop_translate_text(text, language)
            for token, value in tokens:
                text = text.replace(token, value)
            translated["text"] = text
        if translated.get("options"):
            translated["options"] = [
                dict(option, label=_shop_translate_option(option["label"], language))
                for option in translated["options"]
            ]
        translated_messages.append(translated)
    return translated_messages


def _shop_language_options():
    return _shop_options(
        "🌐 Select a language:",
        [(f"lang:{code}", label) for code, label in SHOP_LANGUAGE_NAMES.items()],
    )


# WhatsApp list rows are capped at 24 characters, so the brand prefix is
# dropped from choice labels and anything still too long gets a short form.
SHOP_LABEL_OVERRIDES = {
    "Toilet Cleaner & Sanitizer": "Toilet Cleaner",
}
_shop_catalog_cache = {"loaded": False, "names": {}, "summaries": {}, "prices": {}}


def _shop_catalog():
    """Catalogue loaded from the CRM portal, refreshed on every real turn.

    The first read seeds the table from the products shipped in code, so the
    assistant and the portal both work from the catalogue rather than from two
    separate sources. `shop_ensure_seeded` is looked up defensively because this
    function is also exercised in isolation without the surrounding module.
    """
    if not _shop_catalog_cache["loaded"]:
        seeder = globals().get("shop_ensure_seeded")
        if seeder is not None:
            seeder()
        shop_refresh_catalog()
    return _shop_catalog_cache


def shop_refresh_catalog():
    """Reload product names, summaries, sizes and prices edited in the CRM portal."""
    global _shop_catalog_cache
    names, summaries, prices = {}, {}, {}
    sizes, custom = {}, []
    removed = set()
    try:
        ensure_shop_tables()
        with get_db() as (cursor, connection):
            cursor.execute("SELECT product_id, display_name, summary FROM shop_products")
            for row in cursor.fetchall():
                if row[1]:
                    names[row[0]] = str(row[1]).strip()
                if row[2]:
                    summaries[row[0]] = str(row[2]).strip()
            cursor.execute("SELECT product_id, pack_size, price FROM shop_product_prices")
            for row in cursor.fetchall():
                if row[2] is not None:
                    prices[f"{row[0]}|{row[1]}"] = float(row[2])
            # Products added from the CRM portal are stored alongside the built-in
            # range; their pack sizes come from their own table.
            cursor.execute("""
                SELECT product_id, display_name, summary FROM shop_products
                WHERE is_custom = TRUE ORDER BY position, product_id
            """)
            for row in cursor.fetchall():
                custom.append({"id": row[0],
                               "name": (row[1] or "").strip(),
                               "summary": (row[2] or "").strip(),
                               "sizes": []})
            # Every product whose sizes have been set in the portal. The product
            # id is recorded even when the size list is empty, so clearing the
            # sizes in the editor is not undone by the defaults in code.
            cursor.execute("""
                SELECT DISTINCT product_id FROM shop_product_sizes
            """)
            for row in cursor.fetchall():
                sizes.setdefault(str(row[0]), [])
            cursor.execute("""
                SELECT product_id, pack_size FROM shop_product_sizes ORDER BY product_id, position
            """)
            for row in cursor.fetchall():
                sizes.setdefault(str(row[0]), []).append(str(row[1]))
            # Removals are part of the catalogue state: the customer's list must
            # honour them, not just the editor.
            cursor.execute("SELECT product_id FROM shop_product_removed")
            removed = {str(row[0]) for row in cursor.fetchall()}
    except Exception as e:
        print(f"catalog load error: {e}")
    for product in custom:
        product["sizes"] = sizes.get(product["id"], [])
    _shop_catalog_cache = {"loaded": True, "names": names, "summaries": summaries,
                           "prices": prices, "sizes": sizes, "custom": custom,
                           "removed": removed}
    return _shop_catalog_cache


def shop_seed_catalog():
    """Copy the products shipped in code into the catalogue tables, once.

    The assistant reads its names, descriptions and unit sizes from the portal,
    so the products that only existed in code would otherwise be invisible to
    anyone editing them. A product that already has a catalogue row is left
    alone, which means edits and deletions survive a later restart.

    Returns the number of products seeded.
    """
    seeded = 0
    try:
        ensure_shop_tables()
        # Read the cache directly rather than through _shop_catalog(), which
        # would call back into this function while it is running.
        catalog = _shop_catalog_cache if _shop_catalog_cache.get("loaded") \
            else shop_refresh_catalog()
        # Anything already managed in the portal, by id.
        known = set(catalog.get("names") or {})
        known.update(catalog.get("sizes") or {})
        known.update(product["id"] for product in (catalog.get("custom") or []))
        with get_db() as (cursor, connection):
            # A product removed on purpose must stay removed, so the code default
            # is not copied back on the next start.
            cursor.execute("SELECT product_id FROM shop_product_removed")
            removed = {str(row[0]) for row in cursor.fetchall()}
            for position, base in enumerate(BRILLIANT_PRODUCTS):
                if base["id"] in known or base["id"] in removed:
                    continue
                cursor.execute("""
                    INSERT INTO shop_products (product_id, display_name, summary,
                                               is_custom, position, updated_at)
                    VALUES (%s, %s, %s, FALSE, %s, NOW())
                    ON CONFLICT (product_id) DO NOTHING
                """, (base["id"], base["name"], base["summary"], position))
                for index, size in enumerate(base["sizes"]):
                    cursor.execute("""
                        INSERT INTO shop_product_sizes (product_id, pack_size, position)
                        VALUES (%s, %s, %s)
                        ON CONFLICT (product_id, pack_size) DO NOTHING
                    """, (base["id"], size, index))
                seeded += 1
            connection.commit()
        if seeded:
            # The cache is now stale, so the next turn reads the seeded rows.
            shop_refresh_catalog()
            print(f"catalogue seeded with {seeded} product(s) from the code defaults")
    except Exception as e:
        print(f"catalog seed error: {e}")
    return seeded


def shop_all_products():
    """The full sellable range: the built-in products plus CRM additions.

    Pack sizes come from the catalogue whenever they have been set there, so the
    sizes a customer is offered are exactly the ones the product shows in the
    portal. The sizes in code are only a starting point. WhatsApp renders the
    browse list as a single list message with at most ten rows, so the combined
    range is the figure that has to fit that limit.
    """
    catalog = _shop_catalog()
    names = catalog.get("names") or {}
    summaries = catalog.get("summaries") or {}
    sizes = catalog.get("sizes") or {}
    removed = catalog.get("removed") or set()
    products = []
    for index, base in enumerate(BRILLIANT_PRODUCTS):
        if base["id"] in removed:
            # Deleted in the portal. The code default must not reappear in the
            # customer's list, otherwise a removal would only last until the
            # next worker start.
            continue
        products.append({
            "id": base["id"],
            "index": index,
            # A CRM rename applies to the browsing name as well as the detail view.
            "name": names.get(base["id"]) or base["name"],
            "base_name": base["name"],
            "summary": summaries.get(base["id"]) or base["summary"],
            # An empty override list is respected, so a size the portal removed
            # never comes back from the code default.
            "sizes": list(sizes[base["id"]]) if base["id"] in sizes else list(base["sizes"]),
            "custom": False,
        })
    seen = {product["id"] for product in products}
    for product in (catalog.get("custom") or []):
        if not product.get("name") or not product.get("sizes"):
            # A product with no name or no pack size cannot be ordered, so it is
            # kept out of the customer's list until the CRM finishes setting it up.
            continue
        if product["id"] in seen:
            # A row can exist in the portal under an id that has since shipped in
            # code. Emitting it twice would show the customer the same product
            # twice and quietly consume one of the ten browse rows.
            continue
        seen.add(product["id"])
        products.append({
            "id": product["id"],
            "index": None,
            "name": product["name"],
            "base_name": product["name"],
            "summary": product.get("summary") or "",
            "sizes": list(product["sizes"]),
            "custom": True,
        })
    return products


def _shop_product(category_index):
    """The catalogue product at a position, with CRM overrides applied.

    Positions follow shop_all_products(), so an index past the built-in range is
    a product added from the CRM portal.
    """
    products = shop_all_products()
    try:
        position = int(category_index)
    except (TypeError, ValueError):
        return None
    if position < 0 or position >= len(products):
        return None
    entry = products[position]
    catalog = _shop_catalog()
    return {
        "id": entry["id"],
        "name": catalog["names"].get(entry["id"]) or entry["name"],
        "base_name": entry["base_name"],
        "summary": catalog["summaries"].get(entry["id"]) or entry["summary"],
        "sizes": list(entry["sizes"]),
    }


def _shop_short_name(name):
    """Product name as shown on a WhatsApp choice, without the brand prefix."""
    name = str(name or "").strip()
    if name in SHOP_LABEL_OVERRIDES:
        return SHOP_LABEL_OVERRIDES[name]
    prefix = f"{BRAND_NAME} "
    return name[len(prefix):] if name.startswith(prefix) else name


# A translated choice can be a little longer than the English it replaces, and
# the label is built before the language is known, so room is kept for the
# longest translation so a label that fits in English still fits afterwards.
SHOP_LABEL_TRANSLATION_HEADROOM = 3


def _shop_cart_line_labels(cart):
    """The per-line cart choices, named when a name is short and unique enough.

    A WhatsApp list row holds 24 characters and a product name is free text an
    administrator can type, so a name does not always fit beside an action. Two
    pack sizes of one product would also produce two identical choices, so a
    name is used only while every name in the cart fits and none repeats. The
    style is settled once for the whole cart rather than line by line: a list
    that mixed names and numbers would leave the customer guessing which line
    each choice belonged to. The cart body numbers its lines, so the numbered
    style always identifies one.
    """
    budget = WA_LIST_ROW_TITLE_LIMIT - SHOP_LABEL_TRANSLATION_HEADROOM
    names = [_shop_short_name(item["name"]) for item in cart]
    named = [(f"Qty — {name}", f"Remove — {name}") for name in names]
    numbered = [(f"Change quantity — #{index + 1}", f"Remove — #{index + 1}")
                for index in range(len(cart))]
    usable = (len(set(names)) == len(names) and
              all(max(len(qty), len(remove)) <= budget for qty, remove in named))
    labels = {}
    for index, (qty, remove) in enumerate(named if usable else numbered):
        labels[f"qty:{index}"] = qty
        labels[f"rm:{index}"] = remove
    return labels


def _shop_product_at(value):
    """Clamp a stored product position to a real product. Returns (product, index)."""
    entries = shop_all_products()
    if not entries:
        return None, 0
    try:
        index = int(value)
    except (TypeError, ValueError):
        index = 0
    index = max(0, min(index, len(entries) - 1))
    return _shop_product(index), index


def _shop_first_name(display_name):
    """The part of a WhatsApp profile name to greet someone by.

    Meta returns whatever the person typed into their own profile, so it can be
    a full name, a business name or an emoji-laden alias. Only the first token
    is used, and anything that is not a name falls back to a neutral greeting.
    """
    name = " ".join(str(display_name or "").split()).strip()
    if not name:
        return ""
    # Drop trailing decorations such as "(Sales)" or "- Harare".
    for separator in ("(", "[", "{", "|", ",", "/"):
        if separator in name:
            name = name.split(separator, 1)[0].strip()
    if not name:
        return ""
    first = name.split(" ")[0]
    # A greeting needs letters, not digits or punctuation only.
    if not any(character.isalpha() for character in first):
        return ""
    return first[:40]


def shop_greeting(cart=None, staff=False, display_name=None, language="en", short=False):
    """The main menu.

    `short` is used when the menu is re-shown mid-conversation: repeating the
    full welcome on every return made the thread noisy and pushed the choices
    below the fold, so a returning customer just gets the prompt.
    """
    count = sum(item["qty"] for item in (cart or []))
    cart_label = "View Cart"
    if count:
        cart_label = f"View Cart ({count} item{'s' if count != 1 else ''})"
    options = [("shop", "Shop"), ("search", "Search Products"), ("cart", cart_label),
               ("orders", "My orders"),
               ("support", "Contact us"), ("about", "About Us"),
               ("support_human", "Talk to a human")]
    if staff:
        options.append(("switch_staff", "Switch to Staff"))
    options.append(("language", "Language"))

    if short:
        # One line only, so the choices stay visible without scrolling, but the
        # name is kept so the assistant still reads as a conversation rather
        # than a machine.
        first_name = _shop_first_name(display_name)
        body = (f"What would you like to do next, *{first_name}*?"
                if first_name else "What would you like to do next?")
        return _shop_options(body, options)

    first_name = _shop_first_name(display_name)
    if first_name:
        opening = f"👋 Hello *{first_name}*, welcome to *{BRAND_NAME}*!"
    else:
        opening = f"👋 Welcome to *{BRAND_NAME}*!"

    body = (
        f"{opening}\n"
        f"I am the {COMPANY_SYSTEM_CONTACT['name']} assistant.\n\n"
        "🛍️ Browse the range and build an order\n"
        "🔎 Search for a product by name\n"
        "🛒 Review your cart and check out\n"
        "📦 Track or cancel an order\n"
        "🙋 Ask for a person whenever you prefer\n\n"
        "What would you like to do?"
    )
    return _shop_options(body, options)


def _shop_category_list():
    options = [(f"cat:{index}", _shop_short_name(_shop_product(index)["name"]))
               for index in range(len(shop_all_products()))]
    return _shop_options(
        f"🛍️ *Browse Products*\n{BRAND_NAME} — household, cleaning and personal care.\n\n"
        "Select a category to browse:",
        options,
    )


def _shop_product_list(category_index):
    product = _shop_product(category_index)
    return _shop_options(
        f"🧴 *{product['name']}*\n\n{product['summary']}\n\n"
        f"Available pack sizes: {', '.join(product['sizes'])}",
        [(f"prod:{category_index}", "Choose pack size")],
    )


def _shop_size_list(product, category_index):
    """The pack size prompt.

    Marked to always render as a WhatsApp list: a product may offer up to ten
    sizes, and reply buttons stop at three. Each row shows the price when one has
    been set, so the customer is not choosing blind.
    """
    def label(index, size):
        unit = shop_price({"id": product["id"], "size": size})
        if unit is None:
            return size
        return f"{size} — {PAYNOW_CURRENCY} {unit:.2f}"

    size_options = [(f"size:{index}", label(index, size))
                    for index, size in enumerate(product["sizes"])]
    prompt = _shop_options(
        f"📦 *{product['name']}*\n\nWhich pack size would you like?",
        size_options,
    )
    prompt["force_list"] = True
    return prompt


def _shop_line_amounts(item):
    """(unit_price, line_total) for a cart line. Either may be None.

    A price is only ever shown when the business has actually set one, so the
    assistant can never invent a figure for a customer.
    """
    unit = shop_price(item)
    if unit is None:
        return None, None
    return unit, round(unit * int(item.get("qty") or 0), 2)


def _shop_cart_summary(cart):
    """The itemised basket, with money wherever a price has been set.

    A line with no price says so rather than being left blank: an absent figure
    beside a priced line reads as free, which is the wrong thing for a customer
    to believe about a money document.
    """
    lines = []
    for index, item in enumerate(cart, start=1):
        unit, line_total = _shop_line_amounts(item)
        line = f"{index}. {item['name']} ({item['size']}) × {item['qty']}"
        if unit is None:
            line += "\n    _price on request_"
        else:
            line += (f"\n    {PAYNOW_CURRENCY} {unit:.2f} each — "
                     f"*{PAYNOW_CURRENCY} {line_total:.2f}*")
        lines.append(line)
    return "\n".join(lines)


def _shop_cart_total_line(cart):
    """The amount due, or an honest statement of what is still to be priced."""
    total = shop_cart_total(cart)
    if total is not None:
        return f"*Total: {PAYNOW_CURRENCY} {total:.2f}*"

    priced = 0.0
    unpriced = 0
    for item in cart or []:
        unit, line_total = _shop_line_amounts(item)
        if unit is None:
            unpriced += 1
        else:
            priced += line_total
    if priced:
        return (f"*Priced so far: {PAYNOW_CURRENCY} {priced:.2f}*\n"
                f"{unpriced} item{'s' if unpriced != 1 else ''} still to be priced — "
                "our sales team will confirm.")
    return "Our sales team will confirm the prices and the total on quotation."


def _shop_cart_message(cart):
    if not cart:
        return _shop_options(
            "🛒 *Your cart is empty*\n\nBrowse the range or search for a product to get started.",
            [("shop", "Browse products"), ("search", "Search products")],
        )
    total = sum(item["qty"] for item in cart)
    labels = _shop_cart_line_labels(cart)
    options = [("shop", "Add more products"), ("checkout", "Check out")]
    options += [(f"qty:{index}", labels[f"qty:{index}"]) for index in range(len(cart))]
    options += [(f"rm:{index}", labels[f"rm:{index}"]) for index in range(len(cart))]
    options.append(("clear", "Empty the cart"))
    return _shop_options(
        f"🛒 *Your cart* — {total} item{'s' if total != 1 else ''}\n\n"
        f"{_shop_cart_summary(cart)}\n\n"
        f"{_shop_cart_total_line(cart)}\n\n"
        "What would you like to do?",
        options,
    )


def _shop_search_prompt():
    return _shop_text(
        "🔎 *Search Products*\n\nType a product name or keyword — for example *bleach*, *jelly*, "
        "*pine* or *dish*."
    )


def _shop_search_results(cart, query):
    query = (query or "").strip().lower()
    entries = shop_all_products()
    matches = [
        (index, entry) for index, entry in enumerate(entries)
        if query in entry["name"].lower() or query in entry["summary"].lower()
    ]
    if not matches:
        messages = [_shop_text(
            f"😕 I could not find anything for “{query}”.\n\nTry another keyword, or browse the full range."),
            _shop_options("You can also:", [("shop", "Browse all categories")])]
        return "search", {}, messages
    options = [(f"prod:{index}", _shop_short_name(_shop_product(index)["name"]))
               for index, entry in matches]
    messages = [_shop_options(
        f"🔎 *Search results for “{query}”* — {len(matches)} product"
        f"{'s' if len(matches) != 1 else ''} found:",
        options)]
    return "search_results", {"query": query}, messages


def _shop_support():
    return [_shop_options(
        "☎️ *Customer Support*\n\nHow would you like to contact Brilliant Chemicals Sales?",
        [("support_call", "Call us"),
         ("support_msg", "Message us"),
         ("support_human", "Talk to a human")],
    )]


def _shop_about():
    phones = COMPANY_SYSTEM_CONTACT["phones"]
    return [_shop_options(
        "🏢 *About Brilliant Chemicals (Pvt) Ltd*\n\n"
        "We are a Zimbabwean company, registered as *Vivid Chemicals*, that manufactures, markets and "
        f"distributes high quality domestic household and personal care products under our brand *{BRAND_NAME}*.\n\n"
        f"• *Brand:* {BRAND_NAME} — a registered trademark, proudly SAZ approved\n"
        "• *Vision:* To improve the quality of life in all households of all nations by providing high "
        "quality household and personal care products at affordable prices\n"
        "• *Quality:* Supplier rating, incoming raw material inspection and finished goods inspection, so "
        "our products are consistently of high quality and always meet customer needs\n"
        "• *Strengths:* A lean and efficient structure, modern high capacity production, and an "
        "experienced and energetic leadership team\n"
        "• *Values:* Passion for customers, trust and respect for individuals, uncompromising integrity, "
        "results through teamwork, and speed and agility\n\n"
        "*Visit us:* Number 7529, Tynwald South, Harare, Zimbabwe (8:00 AM – 5:00 PM)\n"
        f"*Call:* {phones[0]} / {phones[1]}\n"
        f"*Email:* {COMPANY_SYSTEM_CONTACT['email']}",
        [("shop", "Shop our products"), ("support", "Talk to Support")],
    )]


def _shop_save_order(state, channel, wa_number=None, customer=None, payment_method=None,
                     amount=None, payment_status="unpaid", delivery_method=None):
    cart = state.get("cart") or []
    if not cart:
        return None
    customer = customer or {}
    reference = f"{SHOP_ORDER_PREFIX}{datetime.now().strftime('%y%m%d')}-{random.randint(1000, 9999)}"
    wa_number = str(wa_number)[-15:] if wa_number else None
    # Collection orders have no address, so the delivery column must be set even
    # when the customer never typed one.
    method = delivery_method or customer.get("delivery_method") or "collection"
    try:
        # The order needs its own tables plus the conversation index it links to;
        # both are created here so a fresh worker can still take an order.
        ensure_shop_tables()
        ensure_crm_tables()
        # A customer who never typed a name still has a WhatsApp profile name;
        # fall back to it so the order and the CRM row are not just a number.
        typed_name = (customer.get("name") or "").strip()
        if not typed_name:
            typed_name = crm_best_display_name(wa_number) or ""
        chat_id = crm_chat_id(wa_number,
                              display_name=typed_name or customer.get("company"),
                              channel=channel) if wa_number else None
        address = (customer.get("delivery_address") or "").strip() or None
        with get_db() as (cursor, connection):
            cursor.execute("""
                INSERT INTO shop_orders (reference, customer_name, company, phone, email,
                                         delivery_address, channel, wa_number, chat_id, notes,
                                         item_count, payment_method, payment_status, payment_amount,
                                         delivery_method, created_at)
                VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, NOW())
                RETURNING id
            """, (reference, typed_name or None, customer.get("company"), customer.get("phone"),
                  customer.get("email"), address if method == "delivery" else None, channel,
                  wa_number, chat_id, customer.get("notes"),
                  sum(item["qty"] for item in cart), payment_method, payment_status, amount,
                  method))
            order_id = cursor.fetchone()[0]
            for item in cart:
                # The price is captured now, at the moment of sale, so the
                # receipt stays accurate after a later repricing.
                cursor.execute("""
                    INSERT INTO shop_order_items (order_id, product, pack_size, quantity,
                                                  unit_price, created_at)
                    VALUES (%s, %s, %s, %s, %s, NOW())
                """, (order_id, item["name"], item["size"], item["qty"], shop_price(item)))
            connection.commit()
    except Exception as e:
        print(f"order save error: {e}")
        return None
    return reference


# ------------------------------------------------------------------ navigation --
# Customers can always step back one menu or jump straight to the main menu.
SHOP_BACK_WORDS = ("b", "back", "previous", "previous menu", "go back", "return")
SHOP_MENU_WORDS = ("m", "menu", "main menu", "mainmenu", "home", "reset", "start", "restart", "0")
# The cart's checkout choice is labelled in the customer's own language, so the
# words on the button have to work when typed as well as tapped - the same
# courtesy the menu and order-list words already get. Only the words that are
# actually printed on the button, so nothing else gains a new meaning.
SHOP_CHECKOUT_WORDS = ("check out", "pedzisa kutenga", "qedela ukuthenga")

# Button ids and navigation words are the assistant's own vocabulary, not
# something a customer typed. Shielding them from translation hides them from it:
# the cart reply contains the word "cart", so "Your cart is empty" and the cart
# heading could never be translated while "cart" was protected. Only free text is
# protected now.
SHOP_RESERVED_WORDS = frozenset({
    "shop", "search", "cart", "support", "about", "language", "checkout", "clear",
    "paynow", "paylater", "confirm_order", "support_human", "paid_check",
    "delivery", "collection", "none", "back", "previous", "menu", "home", "reset",
    "restart", "start", "b", "m", "yes", "y", "no", "n", "ok", "later", "cancel",
    "skip", "help", "en", "sn", "nd",
})


def _shop_preserved_command(command):
    """The customer's own input, unless it is one of the assistant's own words."""
    value = (command or "").strip()
    if not value or value.lower() in SHOP_RESERVED_WORDS:
        return ""
    return value


# Every order reference begins with this. It is also how a reference is
# recognised when a customer types or pastes one back into the chat.
SHOP_ORDER_PREFIX = "BC-"


def _shop_render(step, ctx, cart, customer=None, staff=False, wa_number=None,
                 display_name=None, language="en"):
    """Rebuild the prompt for a step without consuming input.

    Used by Back and by the language detour to put the customer back where they
    were. Every step the engine can store in its history needs a branch here,
    and each one reuses the engine's own prompt builder so the restored prompt
    cannot drift from the one the customer first saw.
    """
    ctx = ctx or {}
    customer = customer or {}
    if step == "category":
        return [_shop_category_list()]
    if step == "product":
        _product, index = _shop_product_at(ctx.get("product", 0))
        return [_shop_product_list(index)]
    if step == "size":
        product, index = _shop_product_at(ctx.get("product", 0))
        return [_shop_size_list(product, index)]
    if step == "qty":
        product, index = _shop_product_at(ctx.get("product", 0))
        size = product["sizes"][min(ctx.get("size", 0), len(product["sizes"]) - 1)]
        return [_shop_text(f"📦 *{product['name']}* — {size}\n\nHow many units would you like?")]
    if step == "cart_qty":
        return [_shop_cart_qty_prompt()]
    if step == "search":
        return [_shop_search_prompt()]
    if step == "search_results":
        _, new_ctx, messages = _shop_search_results(cart, ctx.get("query", ""))
        return messages
    if step == "cart":
        return [_shop_cart_message(cart)]
    if step == "orders":
        return [_shop_orders_menu(wa_number)]
    if step == "order_cancel_confirm":
        reference = ctx.get("cancel_reference") or ""
        order = next((row for row in shop_customer_orders(wa_number, limit=10)
                      if row["reference"] == reference), None)
        if order and order["cancellable"]:
            return [_shop_cancel_prompt(order)]
        # The order moved on while the customer was deciding, so the list is the
        # only truthful thing to show.
        return [_shop_orders_menu(wa_number)]
    if step == "about":
        return _shop_about()
    if step == "support":
        return _shop_support()
    if step == "support_msg":
        return [_shop_text(
            "✍️ Type your message and our sales team will get back to you. Include your name, "
            "company and contact number so we can respond quickly.")]
    if step == "language":
        return [_shop_language_options()]
    if step == "order_name":
        return [_shop_text("📝 Let's set up your order.\n\nWhat is your *full name*?")]
    if step == "order_company":
        return [_shop_text("Which *company* are you ordering for? (Type *none* if you are buying for yourself.)")]
    if step == "order_phone":
        return [_shop_text("What is the best *phone number* to reach you on?")]
    if step == "order_fulfilment":
        return [_shop_options("How would you like to receive this order?",
                              [("delivery", "Deliver to my address"),
                               ("collection", "Collect from the shop")])]
    if step == "order_address":
        return [_shop_order_address_prompt(customer)]
    if step == "order_confirm":
        return _shop_order_confirmation(cart, customer)
    if step == "payment":
        return [_shop_payment_prompt(customer)]
    if step == "pay_phone":
        return [_shop_pay_phone_prompt(ctx.get("phone"))]
    if step == "pay_wait":
        return _shop_pay_wait_prompt(ctx.get("amount"))
    return [shop_greeting(cart, staff, display_name, language)]


def _shop_order_confirmation(cart, customer):
    summary = _shop_cart_summary(cart) or "—"
    delivering = (customer.get("delivery_method") or "collection") == "delivery"
    lines = [
        "✅ *Please confirm your order*",
        "",
        f"*Name:* {customer.get('name', '')}",
        f"*Company:* {customer.get('company', '')}",
        f"*Phone:* {customer.get('phone', '')}",
        f"*Receive by:* {'Delivery to your address' if delivering else 'Collection from our shop'}",
    ]
    if delivering:
        lines.append(f"*Delivery address:* {customer.get('delivery_address', '')}")
    lines += ["", f"*Items:*\n{summary}", "", _shop_cart_total_line(cart)]
    note = _shop_delivery_note(customer)
    if note:
        lines += ["", note]
    lines += ["", "Place this order now?"]
    return [_shop_options("\n".join(lines),
                          [("confirm_order", "Yes, submit"), ("cart", "Back to cart")])]


def _shop_order_state_text(order):
    """How one order reads to the customer, worst state first."""
    if order["cancelled"]:
        return "Cancelled"
    if order["paid"]:
        # How the money was taken is part of what "paid" means to a customer
        # checking their own order, so it is named whenever it is recorded.
        label = _shop_payment_method_label(order.get("payment_method"))
        return f"Paid {label}" if label else "Paid"
    if order["fulfilled"]:
        return "Fulfilled"
    if order["awaiting_pin"]:
        return "Waiting for your EcoCash PIN"
    return "Not paid yet"


def _shop_money_text(amount):
    return f"{PAYNOW_CURRENCY} {amount:.2f}" if amount is not None else "to be confirmed"


def _shop_pay_later_label(customer):
    """Where the money will change hands, now that the fulfilment is known.

    Both phrasings stay inside WhatsApp's 24-character list-row title limit,
    which the longer "Place the order and pay later" did not.
    """
    return "Pay on delivery" if _shop_paying_on_delivery(customer) else "Pay at the shop"


def _shop_paying_on_delivery(customer):
    return (customer or {}).get("delivery_method") == "delivery"


def _shop_pay_later_method(customer):
    """The stored method for an order the customer will pay in person.

    Cash at the counter and cash on the doorstep are different events to the
    business - one is taken before the goods leave, the other after - so the
    record says which rather than a single vague "later".
    """
    return "delivery" if _shop_paying_on_delivery(customer) else "shop"


# ------------------------------------------------------------------- payment --
# The vocabulary stored on shop_orders.payment_method. EcoCash is settled by the
# gateway; the rest are taken by hand, by whoever is holding the goods, so the
# record has to say which one - otherwise neither a receipt nor the chatbot can
# tell a customer where the money they handed over was taken.
SHOP_PAYMENT_METHODS = ("ecocash", "shop", "delivery", "other")

SHOP_PAYMENT_METHOD_LABELS = {
    "ecocash": "via EcoCash",
    "shop": "at the shop",
    "delivery": "on delivery",
    "other": "by other means",
}

# `later` is what an order was once saved with before the customer had chosen,
# and `pay_later` spells the same thing; neither names a way of paying, so an
# order carrying one is reported as having no recorded method rather than being
# guessed at.
SHOP_METHODLESS = ("", "later", "pay_later", "none", "unknown")


def _shop_payment_method(value):
    """A stored method reduced to the vocabulary above, or '' when it names none."""
    text = str(value or "").strip().lower()
    if text in SHOP_METHODLESS:
        return ""
    if "ecocash" in text or "paynow" in text:
        return "ecocash"
    for method in SHOP_PAYMENT_METHODS:
        if method in text:
            return method
    return "other"


def _shop_payment_method_label(value):
    """What a badge says after "Paid", or '' when the method is not recorded."""
    return SHOP_PAYMENT_METHOD_LABELS.get(_shop_payment_method(value), "")


# Delivery is quoted separately because it depends on where the goods are going
# and who is carrying them, so the cart total is for the goods alone. Saying so
# before the money is paid is what stops a delivery charge reading as a surprise
# on the doorstep.
SHOP_DELIVERY_NOTE = (
    "🚚 *Delivery is charged separately*\n"
    "The amount above covers the goods only. Our sales agent will send you the "
    "delivery cost for your area here on WhatsApp before it is arranged.")


def _shop_delivery_note(customer):
    """The delivery-cost note, or nothing when the customer is collecting."""
    return SHOP_DELIVERY_NOTE if _shop_paying_on_delivery(customer) else ""


def _shop_order_address_prompt(customer):
    """The delivery-address question, with the delivery-cost note attached.

    The note belongs here as much as anywhere: this is the moment the customer
    has chosen delivery, so it is the first chance to say the total is for the
    goods alone.
    """
    return _shop_text_with_note(
        "📍 What is the *delivery address* for this order?\n\n"
        "Please include the suburb and any landmark that helps our driver find you.",
        _shop_delivery_note(customer))


def _shop_text_with_note(text, note):
    """One text message, with the note appended when there is one to give."""
    return _shop_text("\n\n".join(part for part in (text, note) if part))


def _shop_payment_options(customer):
    """The two ways to pay, as short labels.

    The amount deliberately stays in the message body rather than in the label:
    a label long enough to carry it is clipped by WhatsApp before the customer
    ever sees it.
    """
    return [
        ("paynow", "Pay now via EcoCash"),
        ("paylater", _shop_pay_later_label(customer)),
    ]


def _shop_payment_prompt(customer):
    return _shop_options("How would you like to pay?", _shop_payment_options(customer))


def _shop_cart_qty_prompt():
    return _shop_text("How many units would you like?")


def _shop_pay_phone_prompt(phone):
    return _shop_text(
        f"📱 Send the EcoCash prompt to which number?\n\n"
        f"Reply *yes* to use *{phone}*, or type the number to use a different line.")


def _shop_pay_wait_prompt(amount):
    return [
        _shop_text(
            "📲 *Check your phone*\n\n"
            f"An EcoCash prompt for *{PAYNOW_CURRENCY} {float(amount or 0):.2f}* "
            "has been sent. Enter your EcoCash PIN to authorise the payment.\n\n"
            "The prompt expires after a few minutes. I will confirm here as soon as it clears."),
        _shop_options("Once you are done:",
                      [("paid_check", "I have authorised it"),
                       ("paylater", "Pay later instead")]),
    ]


def _shop_orders_menu(wa_number):
    """The customer's own recent orders, with a cancel choice for the open ones.

    Only their own orders are listed, and only the ones that can actually be
    cancelled are offered, so the menu never promises something the next step
    would then refuse.
    """
    orders = shop_customer_orders(wa_number, limit=5)
    if not orders:
        return _shop_options(
            "📦 *My orders*\n\nYou have not placed an order yet.",
            [("shop", "Browse products"), ("cart", "View Cart")])

    lines = ["📦 *My orders*", ""]
    options = []
    for order in orders:
        count = order["items"]
        lines.append(f"*{order['reference']}* — {count} item"
                     f"{'s' if count != 1 else ''}, {_shop_money_text(order['amount'])}")
        lines.append(f"    {order['created_at']} · {_shop_order_state_text(order)}")
        if order["cancellable"]:
            options.append((f"cancel:{order['reference']}", f"Cancel {order['reference']}"))
    lines.append("")
    if options:
        lines.append("Choose an order below to cancel it. Cancelling cannot be undone.")
    else:
        lines.append("None of these can be cancelled here. Ask for a person and we will help.")
    options.append(("support_human", "Talk to a human"))
    options.append(("shop", "Browse products"))
    return _shop_options("\n".join(lines), options)


def _shop_cancel_prompt(order):
    """The confirmation shown before an order is cancelled.

    A cancellation is never actioned from one tap: the reference, the item count
    and the amount are read back to the customer first.
    """
    count = order["items"]
    lines = [
        "⚠️ *Cancel this order?*",
        "",
        f"*Reference:* {order['reference']}",
        f"*Items:* {count} item{'s' if count != 1 else ''}",
        f"*Amount:* {_shop_money_text(order['amount'])}",
        "",
    ]
    if order["awaiting_pin"]:
        lines.append(
            "There is an EcoCash prompt on your phone for this order. If you have already "
            "entered your PIN the payment may still go through, and our sales team will "
            "contact you about it.")
        lines.append("")
    lines.append("Cancelling cannot be undone. Reply *yes* to cancel, or *no* to keep the order.")
    return _shop_options("\n".join(lines),
                         [("cancel_yes", "Yes, cancel it"), ("orders", "Keep it")])


def _shop_cancel_result(ok, reason, detail, order=None):
    """What the customer is told after a cancellation attempt.

    Returns (messages, actions). Every failure that involves money or goods is
    handed to a person rather than left with the assistant, because only a person
    can refund or reopen.
    """
    reference = (detail or {}).get("reference") or ""
    if ok:
        lines = [f"✅ *Order {reference} cancelled.*",
                 "",
                 "Nothing will be delivered for it and no payment is due. You can place a "
                 "new order whenever you like."]
        actions = [{"type": "escalate",
                    "reason": f"Customer cancelled order {reference}",
                    "message": f"The customer cancelled {reference} from the assistant."}]
        if order and order["awaiting_pin"]:
            lines += ["",
                      "⚠️ An EcoCash prompt was already on your phone. If you entered your PIN "
                      "before cancelling, our sales team will contact you about a refund."]
            actions.append({"type": "escalate",
                            "reason": f"Cancelled order {reference} may still be paid",
                            "message": f"{reference} was cancelled while an EcoCash prompt was "
                                       f"outstanding. Check whether the payment landed."})
        return [_shop_text("\n".join(lines))], actions

    blocked = {
        "already_cancelled": f"ℹ️ *{reference}* was already cancelled, so there is nothing to "
                             "do. No payment is due for it.",
        "paid": f"⚠️ *{reference}* has already been paid, so it cannot be cancelled here. "
                "Our sales team will help you with a refund — I have passed this on.",
        "fulfilled": f"⚠️ *{reference}* has already been fulfilled, so it cannot be cancelled "
                     "here. Our sales team will help — I have passed this on.",
        "not_found": "I could not find that order against this number. Ask for a person and we "
                     "will look into it.",
        "error": "😕 Something went wrong, so *nothing was cancelled*. Our sales team will sort "
                 "it out — I have passed this on.",
    }
    message = blocked.get(reason, blocked["error"])
    if reason == "already_cancelled":
        return [_shop_text(message)], []
    return [_shop_text(message)], [{"type": "escalate",
                                    "reason": f"Order {reference} could not be cancelled "
                                              f"({reason})",
                                    "message": message}]


def shop_engine(state, raw_input="", button_id="", channel="web", wa_number=None, display_name=None):
    """Advance the shopping assistant one step.

    Returns (state, messages, actions). The state carries a short history so
    every reply can offer "back one menu" and "main menu".
    """
    state = dict(state or {})
    cart = list(state.get("cart") or [])
    ctx = dict(state.get("ctx") or {})
    step = state.get("step") or "menu"
    customer = dict(state.get("customer") or {})
    history = [entry for entry in (state.get("history") or []) if isinstance(entry, dict)][-12:]
    # Set when the number also belongs to a member of staff, so the customer
    # menu can always offer a way back to the staff assistant.
    staff = bool(state.get("staff"))
    language = _shop_language_code(state.get("language"))
    # The WhatsApp profile name is remembered on the session so every later
    # greeting (after a support message, an order or a language change) still
    # addresses the customer by name.
    if display_name is None:
        display_name = state.get("display_name")
    display_name = " ".join(str(display_name or "").split()).strip() or None
    if display_name:
        state["display_name"] = display_name

    # A conversation with no history is brand new, so its first menu is the full
    # welcome. Any later return to the menu is abbreviated.
    conversation_started = bool(history) or step != "menu"

    def greet():
        """The menu shown when a conversation returns to the start."""
        return shop_greeting(cart, staff, display_name, language,
                             short=conversation_started)

    def welcome():
        """The full introduction, used to open a conversation."""
        return shop_greeting(cart, staff, display_name, language)

    command = (button_id or raw_input or "").strip()

    # Option numbers come from the choices on the previous prompt only, so the
    # navigation shortcuts can never be shadowed by a number.
    previous_options = ctx.get("last_options") or []
    if not previous_options and step == "menu":
        # A brand new conversation opens on the greeting, whose choices have not
        # been stored yet; seed them so a typed number still selects something.
        previous_options = shop_option_ids([greet()])
    unmatched_number = False
    if command.isdigit() and previous_options:
        pick = int(command)
        if 1 <= pick <= len(previous_options):
            command = previous_options[pick - 1]
        else:
            unmatched_number = True
    low = command.lower()
    affirmative_words = {"yes", "y", "confirm", "ok"}
    negative_words = {"no", "later", "pay later"}
    if language == "sn":
        affirmative_words.update(("hongu", "ehe"))
        negative_words.add("kwete")
    elif language == "nd":
        affirmative_words.update(("yebo", "ye"))
        negative_words.add("hatshi")

    def finish(new_step, messages, actions=None, new_ctx=None, new_customer=None, new_history=None):
        saved_ctx = ctx if new_ctx is None else new_ctx
        saved_customer = customer if new_customer is None else new_customer
        # Never let translation touch anything a person typed or was addressed
        # by: their name, their order details and the product they picked. The
        # button they pressed is the assistant's own vocabulary, so it is not
        # protected - doing so would hide its words from the translator.
        preserve = [_shop_preserved_command(command), _shop_first_name(display_name)]
        preserve.extend((saved_customer or {}).values())
        preserve.extend((saved_ctx or {}).values())
        for item in cart:
            preserve.extend((item.get("name"), item.get("size")))
        messages = _shop_translate_messages(messages, language, preserve)
        state["step"] = new_step
        state["cart"] = cart
        state["ctx"] = saved_ctx
        state["ctx"]["last_options"] = shop_option_ids(messages)
        state["customer"] = saved_customer
        state["language"] = language
        kept = history if new_history is None else list(new_history)
        state["history"] = kept[-12:]
        state["nav"] = {"back": bool(state["history"]), "menu": new_step != "menu"}
        return state, messages, actions or []

    def result(new_step, messages, actions=None, new_ctx=None, new_customer=None, new_history=None):
        if new_history is not None:
            return finish(new_step, messages, actions, new_ctx, new_customer, new_history)
        pushed = list(history)
        if new_step != step:
            pushed.append({"step": step, "ctx": ctx})
        return finish(new_step, messages, actions, new_ctx, new_customer, pushed)

    def index_of(value, count, prefix=None):
        value = (value or "").strip().lower()
        if prefix and value.startswith(prefix):
            try:
                number = int(value.split(":", 1)[1])
            except (IndexError, ValueError):
                return None
            return number if 0 <= number < count else None
        return None

    # ------------------------------------------------------- navigation keys
    if low in ("language", "change language", "mutauro", "ulimi"):
        return result("language", [_shop_language_options()], new_ctx={})

    if low in SHOP_MENU_WORDS or (
            low in ({"menyu huru"} if language == "sn" else {"imenyu enkulu"} if language == "nd" else set())):
        return finish("menu", [greet()], new_history=[])

    if low in SHOP_BACK_WORDS or (
            low in ({"dzokera", "kudzokera"} if language == "sn" else {"buyela", "emuva"} if language == "nd" else set())):
        if not history:
            return finish("menu", [greet()], new_history=[])
        previous = history[-1]
        restored = previous.get("step") or "menu"
        restored_ctx = previous.get("ctx") or {}
        if restored == "menu":
            return finish("menu", [greet()], new_history=[])
        return finish(restored, _shop_render(restored, restored_ctx, cart, customer,
                                             staff, wa_number, display_name, language),
                      new_ctx=restored_ctx, new_history=history[:-1])

    # --------------------------------------------------------- global commands
    if step == "language":
        language_choices = {f"lang:{code}": code for code in SHOP_LANGUAGE_NAMES}
        language_choices.update({name.lower(): code for code, name in SHOP_LANGUAGE_NAMES.items()})
        selected_language = language_choices.get(low)
        if selected_language:
            language = selected_language
            previous = history[-1] if history else {"step": "menu", "ctx": {}}
            restored_step = previous.get("step") or "menu"
            restored_ctx = previous.get("ctx") or {}
            restored_messages = ([greet()] if restored_step == "menu" else
                                 _shop_render(restored_step, restored_ctx, cart, customer,
                                              staff, wa_number, display_name, language))
            restored_history = [] if restored_step == "menu" else history[:-1]
            return finish(
                restored_step,
                [_shop_text(f"Language changed to {SHOP_LANGUAGE_NAMES[language]}."),
                 *restored_messages],
                new_ctx=restored_ctx,
                new_history=restored_history,
            )
        return result("language", [_shop_language_options()])

    if low in ("shop", "shop now", "addmore", "shop more"):
        return result("category", [_shop_category_list()])

    if low in ("search", "search products"):
        return result("search", [_shop_search_prompt()])

    if low in ("cart", "view cart", "viewcart"):
        return result("cart", [_shop_cart_message(cart)])

    if low in ("support", "talk to support", "help"):
        return result("support", _shop_support())

    if low in ("about", "about us", "aboutus", "company", "who are you"):
        return result("about", _shop_about())

    if staff and low in ("switch_staff", "staff", "switch to staff", "back to staff"):
        return finish("menu", [_shop_text("✅ Switching you back to the staff assistant…")],
                      actions=[{"type": "switch_staff"}], new_history=[])

    if low in ("support_call", "call"):
        phones = " or ".join(COMPANY_SYSTEM_CONTACT["phones"])
        return result("support", [_shop_options(
            f"📞 Call Brilliant Chemicals on {phones}.\n\n"
            f"Office hours: {COMPANY_SYSTEM_CONTACT['hours']}.\n"
            f"Email: {COMPANY_SYSTEM_CONTACT['email']}",
            [("support_msg", "Message us instead")])])

    if low in ("support_msg", "message"):
        return result("support_msg", [_shop_text(
            "✍️ Type your message and our sales team will get back to you. Include your name, "
            "company and contact number so we can respond quickly.")])

    if low in ("support_human", "human", "talk to a human", "speak to a human"):
        # Hand the conversation to a person: the caller escalates it and the
        # assistant stays silent until an agent hands it back.
        return result("menu", [
            _shop_text(
                "🙋 *Connecting you to a person*\n\n"
                "A member of our sales team has been notified and will reply here shortly.\n\n"
                "You can keep browsing in the meantime — the assistant will stay quiet "
                "while an agent is with you."),
            greet(),
        ], actions=[{"type": "escalate", "reason": "Customer asked for a human agent"}],
            new_history=[])

    if low in ("shona", "ndebele", "english") and step != "language":
        # Language names typed outside the selector open it rather than changing
        # the conversation unexpectedly.
        return result("language", [_shop_language_options()], new_ctx={})

    if low in ("clear", "empty cart"):
        cart = []
        return result("cart", [_shop_text("🧺 Your cart has been emptied."), _shop_cart_message(cart)])

    # ------------------------------------------------------ orders and cancelling
    if low in ("orders", "my orders", "order history", "maodha angu", "ama-oda ami"):
        return result("orders", [_shop_orders_menu(wa_number)])

    # A cancel choice from the list, or a reference the customer typed or pasted
    # back into the chat. Only their own open orders are offered, and a reference
    # is only read as one when it looks like one.
    cancel_reference = ""
    if low.startswith("cancel:") or low.startswith("cancel "):
        cancel_reference = command.split(":", 1)[1].strip() if ":" in command \
            else command.split(" ", 1)[1].strip()
    elif step in ("menu", "orders") and command.upper().startswith(SHOP_ORDER_PREFIX):
        cancel_reference = command.strip().upper()

    if cancel_reference:
        order = next((row for row in shop_customer_orders(wa_number, limit=10)
                      if row["reference"] == cancel_reference), None)
        if order and order["cancellable"]:
            return result("order_cancel_confirm", [_shop_cancel_prompt(order)],
                          new_ctx=dict(ctx, cancel_reference=cancel_reference))
        # Nothing to confirm: say why rather than opening a confirmation that
        # would fail on the next tap.
        messages, actions = _shop_cancel_result(
            False, "not_found" if not order else order["blocked_reason"],
            {"reference": cancel_reference}, order)
        return result("orders", messages + [_shop_orders_menu(wa_number)], actions=actions)

    if step == "order_cancel_confirm":
        reference = ctx.get("cancel_reference") or ""
        order = next((row for row in shop_customer_orders(wa_number, limit=10)
                      if row["reference"] == reference), None)
        if low == "cancel_yes" or low in affirmative_words or low in ("hongu", "ehe", "yebo"):
            ok, reason, detail = shop_cancel_order(reference, wa_number)
            messages, actions = _shop_cancel_result(ok, reason, detail, order)
            return result("menu", messages + [greet()], actions=actions, new_history=[])
        if low == "orders" or low in negative_words or low in ("kwete", "cha", "hayi"):
            return result("orders", [
                _shop_text(f"👍 *{reference}* is unchanged."),
                _shop_orders_menu(wa_number)])
        # Anything else re-asks rather than guessing at a destructive answer.
        if order:
            return result("order_cancel_confirm", [_shop_cancel_prompt(order)])
        return result("orders", [_shop_orders_menu(wa_number)])

    if step == "orders":
        return result("orders", [_shop_orders_menu(wa_number)])

    if low in ("checkout", "order") or low in SHOP_CHECKOUT_WORDS:
        if not cart:
            return result("cart", [_shop_cart_message(cart)])
        return result("order_name", [_shop_text("📝 Let's set up your order.\n\nWhat is your *full name*?")])

    # A number that is not on the current menu should never silently jump levels.
    if unmatched_number and step in ("category", "product", "size", "search_results", "cart", "about", "support", "orders", "order_cancel_confirm"):
        prompt = _shop_render(step, ctx, cart, customer, staff, wa_number, display_name, language)
        return finish(step, prompt + [_shop_text(
            f"🤔 *{command}* is not one of the options above. Please choose from the list, "
            "or use *B* to go back and *M* for the main menu.")])

    # ------------------------------------------------------------------ steps
    if step == "category":
        chosen = index_of(command, len(shop_all_products()), "cat")
        if chosen is None:
            return result("category", [_shop_category_list()])
        return result("product", [_shop_product_list(chosen)], new_ctx={"product": chosen})

    if step == "product":
        if low.startswith("prod:"):
            chosen = index_of(command, len(shop_all_products()), "prod")
            if chosen is not None:
                return result("size", [_shop_size_list(_shop_product(chosen), chosen)],
                              new_ctx={"product": chosen})
        return result("category", [_shop_category_list()])

    if step == "size":
        product, product_index = _shop_product_at(ctx.get("product", 0))
        chosen = index_of(command, len(product["sizes"]), "size")
        if chosen is None:
            return result("size", [_shop_size_list(product, product_index)])
        return result("qty", [_shop_text(
            f"📦 *{product['name']}* — {product['sizes'][chosen]}\n\nHow many units would you like?"
        )], new_ctx={"product": product_index, "size": chosen})

    if step == "qty":
        product, product_index = _shop_product_at(ctx.get("product", 0))
        size = product["sizes"][min(ctx.get("size", 0), len(product["sizes"]) - 1)]
        if not command.isdigit() or int(command) <= 0:
            return result("qty", [_shop_text("Please reply with the number of units you need, for example *10*.")])
        quantity = int(command)
        existing = next((item for item in cart if item["id"] == product["id"] and item["size"] == size), None)
        if existing:
            existing["qty"] += quantity
        else:
            cart.append({"id": product["id"], "name": product["name"], "size": size, "qty": quantity})
        return result("cart", [
            _shop_text(f"✅ Added {quantity} × {product['name']} ({size}) to your cart."),
            _shop_cart_message(cart),
        ])

    if step == "search":
        query = (raw_input or "").strip()
        if not query:
            return result("search", [_shop_search_prompt()])
        new_step, new_ctx, messages = _shop_search_results(cart, query)
        return result(new_step, messages, new_ctx=new_ctx)

    if step == "search_results":
        if low.startswith("prod:"):
            chosen = index_of(command, len(shop_all_products()), "prod")
            if chosen is not None:
                return result("size", [_shop_size_list(_shop_product(chosen), chosen)],
                              new_ctx={"product": chosen})
        if low in ("shop",):
            return result("category", [_shop_category_list()])
        query = (raw_input or "").strip()
        if query:
            new_step, new_ctx, messages = _shop_search_results(cart, query)
            return result(new_step, messages, new_ctx=new_ctx)
        return result("search", [_shop_search_prompt()])

    if step == "cart":
        if low.startswith("rm:"):
            try:
                cart.pop(int(low.split(":", 1)[1]))
            except (ValueError, IndexError):
                pass
            return result("cart", [_shop_cart_message(cart)])
        if low.startswith("qty:"):
            try:
                return result("cart_qty", [_shop_cart_qty_prompt()],
                              new_ctx={"edit": int(low.split(":", 1)[1])})
            except ValueError:
                return result("cart", [_shop_cart_message(cart)])
        if not cart:
            typed = (raw_input or "").strip()
            if typed and not typed.isdigit():
                new_step, new_ctx, messages = _shop_search_results(cart, typed)
                return result(new_step, messages, new_ctx=new_ctx)
        return result("cart", [_shop_cart_message(cart)])

    if step == "cart_qty":
        if command.isdigit() and int(command) > 0 and "edit" in ctx:
            try:
                cart[ctx["edit"]]["qty"] = int(command)
            except (ValueError, IndexError):
                pass
            return result("cart", [_shop_cart_message(cart)])
        return result("cart", [_shop_cart_message(cart)])

    if step == "support_msg":
        message = (raw_input or "").strip()
        if not message:
            return result("support_msg", [_shop_text("Please type your message so our sales team can help you.")])
        return result("menu", [
            _shop_text("✅ Thank you — your message has been passed to our sales team. 🙏 "
                       "Someone will come back to you shortly."),
            greet(),
        ], actions=[{"type": "escalate", "reason": "Customer requested support", "message": message}],
            new_history=[])

    if step == "order_name":
        customer["name"] = (raw_input or "").strip()
        if not customer["name"]:
            return result("order_name", [_shop_text("Please type your full name so we can process your order.")])
        return result("order_company", [
            _shop_text("Which *company* are you ordering for? (Type *none* if you are buying for yourself.)")])

    if step == "order_company":
        customer["company"] = (raw_input or "").strip()
        return result("order_phone", [_shop_text("What is the best *phone number* to reach you on?")])

    if step == "order_phone":
        customer["phone"] = (raw_input or "").strip()
        # How the order reaches the customer changes what we still need to ask,
        # so ask it before the address rather than after.
        return result("order_fulfilment", [_shop_options(
            "How would you like to receive this order?",
            [("delivery", "Deliver to my address"), ("collection", "Collect from the shop")])])

    if step == "order_fulfilment":
        if low in ("delivery", "deliver", "1") or "deliver" in low:
            customer["delivery_method"] = "delivery"
            return result("order_address", [_shop_order_address_prompt(customer)])
        if low in ("collection", "collect", "pickup", "pick up", "2") or "collect" in low:
            # No address to collect: the customer comes to us.
            customer["delivery_method"] = "collection"
            customer["delivery_address"] = ""
            return result("order_confirm", _shop_order_confirmation(cart, customer))
        return result("order_fulfilment", [_shop_options(
            "Please choose how you would like to receive this order.",
            [("delivery", "Deliver to my address"), ("collection", "Collect from the shop")])])

    if step == "order_address":
        customer["delivery_address"] = (raw_input or "").strip()
        return result("order_confirm", _shop_order_confirmation(cart, customer))

    if step == "order_confirm":
        if low == "confirm_order" or low in affirmative_words:
            total = shop_cart_total(cart)
            can_pay = total is not None and paynow_configured()
            # Without a gateway the customer pays whoever hands over the goods, so
            # the method is already known. With one, it is chosen at the next step
            # and written again there once it is.
            reference = _shop_save_order(state, channel, wa_number, customer,
                                         payment_method="ecocash" if can_pay
                                         else _shop_pay_later_method(customer),
                                         delivery_method=customer.get("delivery_method"))
            if not reference:
                return result("order_confirm", [_shop_text(
                    "😕 Sorry, we could not save your order just now. Please try once more, or call "
                    f"{COMPANY_SYSTEM_CONTACT['phones'][0]}.")])
            ctx = {"reference": reference, "amount": total}
            if can_pay:
                return result("payment", [
                    _shop_text_with_note(
                        "🎉 *Order received*\n\n"
                        f"Thank you {customer.get('name', '')}! Your reference is *{reference}*.\n"
                        f"Order total: *{PAYNOW_CURRENCY} {total:.2f}*",
                        _shop_delivery_note(customer)),
                    _shop_payment_prompt(customer),
                ], new_ctx=ctx)

            cart = []
            return result("menu", _shop_order_placed(reference, customer, total, staff=staff,
                                                     display_name=display_name, language=language),
                          actions=[
                {"type": "escalate", "reason": f"New order enquiry {reference}"}],
                new_ctx=ctx, new_history=[])

        if low in ("cart", "back"):
            return result("cart", [_shop_cart_message(cart)])
        return result("order_confirm", _shop_order_confirmation(cart, customer))

    if step == "payment":
        if low in ("paylater", "later", "pay later") or low in negative_words:
            reference = ctx.get("reference")
            # The order was saved as an EcoCash one because the gateway was
            # available. The customer has now chosen otherwise, so the record has
            # to be corrected rather than left claiming EcoCash.
            shop_payment_update(reference, "pay_later", method=_shop_pay_later_method(customer))
            cart = []
            return result("menu", _shop_order_placed(reference, customer, ctx.get("amount"),
                                                     staff=staff, display_name=display_name,
                                                     language=language),
                          actions=[{"type": "escalate",
                                    "reason": f"New order enquiry {reference}"}],
                          new_history=[])
        if low in ("paynow", "pay", "ecocash") or low in affirmative_words:
            phone = str(customer.get("phone") or "").strip() or str(wa_number or "")
            return result("pay_phone", [_shop_pay_phone_prompt(phone)],
                          new_ctx=dict(ctx, phone=phone))
        if low in ("b", "back"):
            return result("order_confirm", _shop_order_confirmation(cart, customer))
        return result("payment", [_shop_payment_prompt(customer)])

    if step == "pay_phone":
        typed = (raw_input or "").strip()
        phone = ctx.get("phone") if low in affirmative_words else typed
        phone = re.sub(r"[^0-9]", "", str(phone or ""))
        if phone.startswith("263"):
            phone = "0" + phone[3:]
        if not (phone.startswith("07") and len(phone) >= 10):
            return result("pay_phone", [_shop_text(
                "That does not look like a Zimbabwean mobile number. "
                "Please send it like *0771234567*, or reply *B* to change your choice.")])
        ok, message, poll_url = paynow_initiate(
            ctx.get("reference"), ctx.get("amount") or 0, phone, customer,
            description=f"Brilliant Chemicals order {ctx.get('reference')}")
        if not ok:
            return result("payment", [
                _shop_text(f"⚠️ {message}\n\nYou can still place the order and pay later."),
                _shop_options("What would you like to do?",
                              [("paynow", "Try EcoCash again"),
                               ("paylater", _shop_pay_later_label(customer))]),
            ], new_ctx=ctx)
        # The customer has now actually chosen EcoCash, so the method is recorded
        # here rather than left to the guess made when the order was saved.
        shop_payment_update(ctx.get("reference"), "pending", poll_url, ctx.get("amount"),
                            method="ecocash")
        cart = []
        return result("pay_wait", _shop_pay_wait_prompt(ctx.get("amount")),
                      actions=[{"type": "escalate",
                                "reason": f"EcoCash payment pending {ctx.get('reference')}"}])

    if step == "pay_wait":
        reference = ctx.get("reference")
        method, status, poll_url, amount = shop_order_payment(reference)
        if (status or "").lower() == "paid":
            cart = []
            return result("menu", [
                _shop_text(f"🎉 *Payment received* — thank you!\n\n"
                           f"Reference *{reference}* is paid and confirmed."),
                greet(),
            ], new_history=[])
        if low in ("paylater", "later", "pay later") or low in negative_words:
            shop_payment_update(reference, "pay_later", method=_shop_pay_later_method(customer))
            cart = []
            return result("menu", _shop_order_placed(reference, customer, amount, paid=False,
                                                     staff=staff, display_name=display_name,
                                                     language=language),
                          new_history=[])
        ok, paynow_status, _payload = paynow_poll(poll_url)
        if ok and paynow_status == "paid":
            shop_payment_update(reference, "paid", paid=True, method="ecocash")
            cart = []
            return result("menu", [
                _shop_text(f"🎉 *Payment received* — thank you!\n\n"
                           f"Reference *{reference}* is paid and confirmed."),
                greet(),
            ], new_history=[])
        if ok and paynow_status in ("cancelled", "failed", "error"):
            shop_payment_update(reference, paynow_status or "failed")
            return result("pay_wait", [
                _shop_text(f"😕 EcoCash reported the payment as *{paynow_status}*. "
                           "You can try again, or place the order and pay later."),
                _shop_options("What would you like to do?",
                              [("paynow", "Try EcoCash again"),
                               ("paylater", "Pay later instead")]),
            ], new_ctx=ctx)
        return result("pay_wait", [
            _shop_text("⏳ EcoCash is still waiting for your PIN. The prompt is on your phone — "
                       "authorise it and then reply *yes*."),
            _shop_options("Once you are done:",
                          [("paid_check", "I have authorised it"),
                           ("paylater", "Pay later instead")]),
        ], new_ctx=ctx)

    return finish("menu", [greet()], new_history=[])


def _shop_order_placed(reference, customer, amount=None, paid=False, staff=False, display_name=None,
                       language="en"):
    """The confirmation shown once an order exists, paid or not.

    An unpaid order still has to be collectable, so the customer is told exactly
    what to do with the reference depending on how they asked to receive it.
    """
    delivering = (customer.get("delivery_method") or "collection") == "delivery"
    lines = ["🎉 *Order confirmed*" if paid else "✅ *Order placed*",
             "",
             f"Thank you {customer.get('name', '')}! Your reference is *{reference}*."]
    if amount is not None and not paid:
        lines.append(f"Amount due: *{PAYNOW_CURRENCY} {float(amount):.2f}*")
    lines.append("")
    if not paid:
        # The reference is the only thing tying this customer to their order when
        # they arrive, so spell out what to do with it.
        lines.append(f"*Keep this reference:* *{reference}*")
        if delivering:
            lines.append(f"Quote it to the deliverer when they bring your order, and pay "
                         f"*{PAYNOW_CURRENCY} {float(amount or 0):.2f}* on delivery.")
        else:
            lines.append(f"Bring it with you to collect from our shop"
                         + (f", and pay *{PAYNOW_CURRENCY} {float(amount or 0):.2f}* there."
                            if amount is not None else "."))
        if delivering:
            # The total is the goods only, so the delivery charge is named here
            # rather than left to be discovered when the order arrives.
            lines.append("")
            lines.append(SHOP_DELIVERY_NOTE)
        lines.append("")
        lines.append(f"Our sales team will confirm "
                     + ("delivery arrangements" if delivering else "when your order is ready")
                     + " within one working day.")
    else:
        lines.append(f"*Reference:* *{reference}*")
        lines.append("Our sales team will be in touch about "
                     + ("delivery." if delivering else "collection."))
    lines.append("")
    lines.append(f"Any questions? Call {COMPANY_SYSTEM_CONTACT['phones'][0]} or email "
                 f"{COMPANY_SYSTEM_CONTACT['email']}.")
    return [_shop_text("\n".join(lines)), shop_greeting(None, staff, display_name, language)]


def _shop_payment_event(reference, event, status, payload=""):
    """Archive every step of a payment so a dispute can be traced."""
    try:
        ensure_shop_tables()
        with get_db() as (cursor, connection):
            cursor.execute("""
                INSERT INTO shop_payment_events (reference, event, status, payload, created_at)
                VALUES (%s, %s, %s, %s, NOW())
            """, (reference, event, status, str(payload)[:2000]))
            connection.commit()
    except Exception as e:
        print(f"payment event error: {e}")


def _paynow_client():
    """Paynow gateway client, configured from the environment."""
    if not paynow_configured():
        return None
    try:
        return Paynow(PAYNOW_INTEGRATION_ID, PAYNOW_INTEGRATION_KEY,
                      PAYNOW_RETURN_URL, PAYNOW_RESULT_URL)
    except Exception as e:
        print(f"paynow client error: {e}")
        return None


def paynow_initiate(reference, amount, phone, customer=None, description=None):
    """Push an EcoCash prompt to a customer's handset. (ok, message, poll_url)."""
    client = _paynow_client()
    if client is None:
        return False, "EcoCash payments are not configured on this deployment.", ""
    customer = customer or {}
    try:
        amount = float(amount or 0)
    except (TypeError, ValueError):
        amount = 0
    if amount <= 0:
        # Paynow raises on a non-positive total, which would otherwise surface as
        # a misleading "could not reach EcoCash".
        return False, "There is no amount to charge for this order.", ""
    # Paynow requires a non-empty auth email for mobile transactions, so a
    # customer who never gave one falls back to the company address.
    auth_email = (customer.get("email") or "").strip() or PAYNOW_AUTH_EMAIL
    try:
        payment = client.create_payment(reference, auth_email)
        payment.add(description or f"Brilliant Chemicals order {reference}", amount)
        response = client.send_mobile(payment, phone, "ecocash")
    except Exception as e:
        print(f"paynow initiate error: {e}")
        _shop_payment_event(reference, "initiate", "error", e)
        return False, "We could not reach EcoCash just now.", ""

    success = getattr(response, "success", False) is True

    # The SDK's response classes declare their fields as bare annotations
    # (`error = str`, `instructions = str`) and `__init__` returns early on an
    # error, so those names fall back to the annotation itself. Reading one
    # without this guard leaks the `str` type into a customer message and into a
    # JSON response, which Flask then refuses to serialise.
    def _field(name):
        value = getattr(response, name, "")
        return value if isinstance(value, str) else ""

    # On an error the SDK also never stores the reason - that assignment sits
    # after the early return - so the raw payload it keeps is the only place the
    # gateway's own words survive.
    raw = getattr(response, "data", None)
    raw = raw if isinstance(raw, dict) else {}

    def _raw(name):
        value = raw.get(name, "")
        if isinstance(value, (list, tuple)):
            value = value[0] if value else ""
        return value if isinstance(value, str) else ""

    poll_url = _field("poll_url") or _raw("pollurl")
    error = _field("error") or _raw("error")
    # On success the SDK stores the text on `instruction`, singular, even though
    # the class annotation is spelled `instructions`.
    instructions = _field("instructions") or _field("instruction") or _raw("instructions")
    # The reason is not always in an `error` field, and the operator needs the
    # gateway's own words to act on a refusal, so the raw payload is recorded
    # when there is nothing readable in the parsed one.
    _shop_payment_event(reference, "initiate", "ok" if success else "error",
                        error or (poll_url if success else str(raw)[:400]))
    if success:
        return True, instructions, poll_url
    return False, error or "EcoCash did not accept the request.", poll_url


def paynow_poll(poll_url):
    """Check a pending transaction. Returns (ok, status, paid)."""
    client = _paynow_client()
    if client is None or not poll_url:
        return False, "", False
    try:
        reply = client.check_transaction_status(poll_url)
    except Exception as e:
        print(f"paynow poll error: {e}")
        return False, "", False
    # `paid` is only ever a real bool when the SDK's __init__ ran to completion;
    # a missing one falls back to the class annotation, which is truthy, so the
    # truth is required rather than merely checked.
    status = getattr(reply, "status", "")
    status = status.strip().lower() if isinstance(status, str) else ""
    return True, status, getattr(reply, "paid", False) is True


def shop_payment_update(reference, status, poll_url=None, amount=None, paid=False, method=None):
    """Record a payment outcome for one order.

    `method` is only written when it is given, so changing a status never
    silently rewrites the way the customer chose to pay.
    """
    try:
        ensure_shop_tables()
        with get_db() as (cursor, connection):
            cursor.execute("""
                UPDATE shop_orders
                SET payment_status = %s,
                    payment_method = COALESCE(%s, payment_method),
                    payment_poll_url = COALESCE(%s, payment_poll_url),
                    payment_amount = COALESCE(%s, payment_amount),
                    paid_at = CASE WHEN %s THEN NOW() ELSE paid_at END
                WHERE reference = %s
            """, (status, method, poll_url, amount, paid, reference))
            connection.commit()
        return True
    except Exception as e:
        print(f"payment update error: {e}")
        return False


def shop_order_payment(reference):
    """(method, status, poll_url, amount) for one order."""
    try:
        ensure_shop_tables()
        with get_db() as (cursor, connection):
            cursor.execute("""
                SELECT payment_method, payment_status, payment_poll_url, payment_amount
                FROM shop_orders WHERE reference = %s
            """, (reference,))
            row = cursor.fetchone()
        return row if row else (None, None, None, None)
    except Exception as e:
        print(f"payment lookup error: {e}")
        return (None, None, None, None)


def _ecocash_msisdn(phone):
    """A Zimbabwean mobile number in the local 07… form EcoCash expects."""
    digits = "".join(character for character in str(phone or "") if character.isdigit())
    if not digits:
        return ""
    # 00263… is the international prefix dialled from a landline.
    if digits.startswith("00"):
        digits = digits[2:]
    if digits.startswith("263"):
        digits = "0" + digits[3:]
    elif not digits.startswith("0"):
        digits = "0" + digits
    return digits


def order_request_ecocash(reference, phone=None, user=None):
    """Send an EcoCash PIN prompt for an order. Returns (ok, message, poll_url).

    The sales person triggers this when the customer says they want to pay by
    EcoCash, so the prompt lands on the customer's own handset and they enter
    their PIN there. The portal never sees the PIN.
    """
    detail = order_detail(reference)
    if not detail:
        return False, "That order could not be found.", ""
    if detail["payment_status"] == "paid":
        return False, "That order is already paid.", ""
    if not paynow_configured():
        return False, "EcoCash is not configured on this deployment.", ""

    amount = detail.get("amount_charged")
    if amount is None:
        amount = detail.get("total")
    if not amount:
        # An unpriced order cannot be pushed to EcoCash: there is no amount to
        # charge, and inventing one would take the wrong money.
        return False, ("This order has no priced lines, so there is no amount to "
                       "charge. Set pack prices in Products & pricing first."), ""

    number = _ecocash_msisdn(phone or detail.get("phone"))
    if len(number) < 9:
        return False, "That order has no usable mobile number to send the prompt to.", ""

    ok, message, poll_url = paynow_initiate(
        reference, amount, number,
        customer={"email": detail.get("email") or ""},
        description=f"Brilliant Chemicals order {reference}")
    if not ok:
        return False, message or "EcoCash did not accept the request.", poll_url

    shop_payment_update(reference, "pending", poll_url=poll_url, amount=amount)
    _shop_payment_event(reference, "requested_from_portal", "pending",
                        f"{number} {amount}")
    log_activity("requested_ecocash_payment", "order",
                 f"Sent an EcoCash prompt to {number} for {PAYNOW_CURRENCY} {amount:.2f}",
                 target=reference,
                 details={"phone": number, "amount": amount}, user=user)
    return True, message or "", poll_url


def order_payment_status(reference, refresh=True):
    """Current payment state for an order, optionally re-checking EcoCash.

    Returns None when there is no such order, so a caller cannot mistake an
    unknown reference for an unpaid one. The customer pays on their own handset,
    so the gateway is the source of truth: a pending order is polled rather than
    assumed, and a confirmed payment is written back once so the receipt and the
    order agree.
    """
    ensure_shop_tables()
    reference = (reference or "").strip()
    if not reference:
        return None
    try:
        with get_db() as (cursor, connection):
            cursor.execute("""
                SELECT payment_method, payment_status, payment_poll_url, payment_amount
                FROM shop_orders WHERE reference = %s
            """, (reference,))
            row = cursor.fetchone()
    except Exception as e:
        print(f"payment status error: {e}")
        return None
    if not row:
        return None
    method, status, poll_url, amount = row
    status = (status or "unpaid").strip().lower()
    paid = status == "paid"

    if refresh and not paid and poll_url:
        ok, gateway_status, gateway_paid = paynow_poll(poll_url)
        if ok:
            if gateway_paid:
                # Settled by the gateway, so the money came in through EcoCash
                # even if the order had been recorded as a pay-later one.
                shop_payment_update(reference, "paid", amount=amount, paid=True, method="ecocash")
                _shop_payment_event(reference, "poll", "paid", gateway_status)
                log_activity("payment_received", "order",
                             f"EcoCash payment received for {reference}",
                             target=reference,
                             details={"amount": amount, "gateway_status": gateway_status})
                status, paid = "paid", True
                # The customer paid from their own handset, so the receipt goes
                # straight to them rather than waiting for someone to send it.
                try:
                    shop_send_receipt(reference)
                except Exception as e:
                    print(f"receipt send skipped: {e}")
            elif gateway_status and gateway_status != status:
                # Cancelled, failed or timed out all mean the same thing to the
                # portal: it is no longer waiting on the customer.
                shop_payment_update(reference, gateway_status, amount=amount)
                _shop_payment_event(reference, "poll", gateway_status, gateway_status)
                status = gateway_status
    method_key = _shop_payment_method(method)
    return {
        "reference": reference,
        "method": method or "",
        "method_key": method_key,
        "method_label": SHOP_PAYMENT_METHOD_LABELS.get(method_key, ""),
        "status": status,
        "paid": paid,
        "amount": float(amount) if amount is not None else None,
        "currency": PAYNOW_CURRENCY,
        "awaiting": bool(poll_url) and not paid and status not in ("cancelled", "failed"),
    }


def order_record_payment(reference, method, user=None):
    """Record money taken by hand for an order. Returns (ok, message).

    EcoCash settles itself through the gateway and writes its own result, but cash
    at the counter and cash on the doorstep are taken by a person, so the sales
    team has to say which one happened. Without that the record cannot tell the
    two apart, and the receipt printed afterwards would have no way of saying
    where the money was taken.
    """
    reference = (reference or "").strip()
    key = _shop_payment_method(method)
    if not reference:
        return False, "That order could not be found."
    if not key:
        return False, "Choose how the customer paid."
    detail = order_detail(reference)
    if not detail:
        return False, "That order could not be found."
    if detail["payment_status"] == "paid":
        return False, "That order is already marked paid."

    amount = detail.get("amount_charged")
    if amount is None:
        amount = detail.get("total")
    if not shop_payment_update(reference, "paid", amount=amount, paid=True, method=key):
        return False, "The payment could not be recorded just now."
    _shop_payment_event(reference, "recorded_by_staff", "paid",
                        f"{key} {amount if amount is not None else ''} {user or ''}".strip())
    log_activity("recorded_payment", "order",
                 f"Recorded {reference} as paid "
                 f"{SHOP_PAYMENT_METHOD_LABELS.get(key, key)}",
                 target=reference,
                 details={"method": key, "amount": amount}, user=user)
    return True, ("Recorded as paid "
                  f"{SHOP_PAYMENT_METHOD_LABELS.get(key, key)}. The receipt can now be "
                  "printed or sent to the customer.")


def _shop_order_owner_key(number):
    """The key an order is stored under, so a lookup matches what was written.

    Orders record `str(wa_number)[-15:]`, which is the convention the inbox and
    the chat link already rely on, so the same normalisation is used here.
    """
    return str(number)[-15:] if number else ""


def shop_customer_orders(wa_number, limit=5):
    """The customer's own recent orders, newest first.

    Scoped to the number the order was placed from, so one number can never see
    another's orders. The amount is the sum of the line prices captured at the
    time of sale, and is left unset when a line was never priced rather than
    being reported as zero.
    """
    owner = _shop_order_owner_key(wa_number)
    if not owner:
        return []
    ensure_shop_tables()
    try:
        with get_db() as (cursor, connection):
            cursor.execute("""
                SELECT orders.reference, COALESCE(orders.item_count, 0),
                       COALESCE(orders.payment_status, 'unpaid'),
                       COALESCE(orders.status, 'new'), orders.created_at,
                       orders.payment_amount, orders.paid_at, orders.fulfilled_at,
                       orders.cancelled_at, orders.payment_poll_url,
                       (SELECT SUM(items.unit_price * items.quantity)
                          FROM shop_order_items items
                         WHERE items.order_id = orders.id
                           AND items.unit_price IS NOT NULL),
                       (SELECT COUNT(*) FROM shop_order_items items
                         WHERE items.order_id = orders.id
                           AND items.unit_price IS NULL),
                       orders.payment_method
                FROM shop_orders orders
                WHERE orders.wa_number = %s
                ORDER BY orders.created_at DESC NULLS LAST, orders.id DESC
                LIMIT %s
            """, (owner, limit))
            rows = cursor.fetchall()
    except Exception as e:
        print(f"customer orders error: {e}")
        return []

    orders = []
    for row in rows:
        paid = (row[2] or "").lower() == "paid" or row[6] is not None
        cancelled = row[8] is not None or (row[3] or "") == "cancelled"
        fulfilled = row[7] is not None or (row[3] or "") == "closed"
        unpriced = int(row[11] or 0)
        if row[5] is not None:
            amount = float(row[5])
        elif unpriced:
            amount = None
        else:
            amount = float(row[10]) if row[10] is not None else None
        if cancelled:
            reason = "cancelled"
        elif paid:
            reason = "paid"
        elif fulfilled:
            reason = "fulfilled"
        else:
            reason = ""
        orders.append({
            "reference": row[0],
            "items": int(row[1] or 0),
            "payment_status": row[2] or "unpaid",
            "payment_method": row[12],
            "status": row[3] or "new",
            "created_at": fmt_time(row[4], "%d %b %Y %H:%M"),
            "amount": amount,
            "unpriced": unpriced,
            "paid": paid,
            "cancelled": cancelled,
            "fulfilled": fulfilled,
            # A prompt on the customer's handset could still be authorised.
            "awaiting_pin": bool(row[9]) and not paid,
            "cancellable": not (cancelled or paid or fulfilled),
            "blocked_reason": reason,
        })
    return orders


def shop_cancel_order(reference, wa_number, user=None):
    """Cancel one of the customer's own orders. Returns (ok, reason, detail).

    Every precondition sits in the UPDATE itself, so a state change between
    reading and writing cannot slip through: the row is only cancelled while it
    is still that customer's own, still open, still unpaid and still unfulfilled.
    `RETURNING` then says whether this call was the one that changed it, which
    makes a repeated tap harmless instead of a second cancellation.
    """
    reference = (reference or "").strip()
    owner = _shop_order_owner_key(wa_number)
    if not reference or not owner:
        return False, "not_found", {}

    ensure_shop_tables()
    try:
        with get_db() as (cursor, connection):
            cursor.execute("""
                UPDATE shop_orders
                SET status = 'cancelled', cancelled_at = NOW()
                WHERE reference = %s
                  AND wa_number = %s
                  AND COALESCE(status, 'new') NOT IN ('cancelled', 'closed')
                  AND fulfilled_at IS NULL
                  AND paid_at IS NULL
                  AND COALESCE(payment_status, 'unpaid') <> 'paid'
                RETURNING reference, COALESCE(item_count, 0)
            """, (reference, owner))
            changed = cursor.fetchone()
    except Exception as e:
        print(f"order cancel error: {e}")
        return False, "error", {}

    if changed:
        _shop_payment_event(reference, "cancelled_by_customer", "cancelled", owner)
        log_activity("customer_cancelled_order", "order",
                     f"Cancelled order {reference} from the assistant",
                     target=reference, details={"wa_number": owner}, user=user)
        return True, "", {"reference": reference, "items": int(changed[1] or 0)}

    # Nothing was changed, so the reason comes from the order itself. The read is
    # scoped to the same number, and a reference belonging to someone else reads
    # exactly like one that does not exist, so it cannot be probed.
    try:
        with get_db() as (cursor, connection):
            cursor.execute("""
                SELECT COALESCE(status, 'new'), COALESCE(payment_status, 'unpaid'),
                       paid_at, fulfilled_at, cancelled_at
                FROM shop_orders WHERE reference = %s AND wa_number = %s
            """, (reference, owner))
            row = cursor.fetchone()
    except Exception as e:
        print(f"order cancel lookup error: {e}")
        return False, "error", {}
    if not row:
        return False, "not_found", {}
    if row[4] is not None or (row[0] or "") == "cancelled":
        return False, "already_cancelled", {}
    if (row[1] or "").lower() == "paid" or row[2] is not None:
        return False, "paid", {}
    if row[3] is not None or (row[0] or "") == "closed":
        return False, "fulfilled", {}
    # The order looks cancellable but the update refused it, so something moved
    # between the two statements. Sending the customer to a person is the only
    # honest answer rather than assuming which.
    return False, "error", {}


def shop_nav_block(nav, language="en"):
    """The navigation footer appended to every customer reply."""
    if not nav or not (nav.get("back") or nav.get("menu")):
        return ""
    lines = []
    if nav.get("back"):
        lines.append("↩️  *B* — back to the previous menu")
    if nav.get("menu"):
        lines.append("🏠  *M* — main menu")
    return "━━━━━━━━━━━━━━━\n" + _shop_translate_text("\n".join(lines), language)


def shop_nav_options(nav, language="en", with_language=False):
    """Navigation choices offered alongside every prompt.

    Language is added only where the prompt carries no choices of its own.
    WhatsApp allows three reply buttons and Back plus Main menu already take two,
    so a prompt with a business choice would be pushed out of buttons and into a
    list just to make room for it.
    """
    options = []
    if nav and nav.get("back"):
        options.append({"id": "b", "label": _shop_translate_option("Back", language)})
    if nav and nav.get("menu"):
        options.append({"id": "m", "label": _shop_translate_option("Main menu", language)})
    if with_language and options:
        options.append({"id": "language", "label": _shop_translate_option("Language", language)})
    return options


# WhatsApp limits: three reply buttons, ten list rows, short titles, and a
# smaller body allowance on button messages than on lists.
WA_BUTTON_LIMIT = 3
WA_BUTTON_TITLE_LIMIT = 20
WA_BUTTON_BODY_LIMIT = 1024
WA_LIST_ROWS_MAX = 10
WA_LIST_ROW_TITLE_LIMIT = 24

# The customer browses products as one WhatsApp list, so the sellable range and
# every product name have to fit WhatsApp's limits or the list cannot be sent.
CATALOG_MAX_PRODUCTS = WA_LIST_ROWS_MAX
CATALOG_NAME_LIMIT = WA_LIST_ROW_TITLE_LIMIT
CATALOG_SUMMARY_LIMIT = 300
CATALOG_PACK_LIMIT = WA_LIST_ROWS_MAX
# Pack sizes are always offered as a WhatsApp list, which tops out at ten rows.
# The navigation rows are added on top of the choices, so the ceiling is ten.
CATALOG_MAX_PACKS_PER_PRODUCT = WA_LIST_ROWS_MAX
# The first WhatsApp body limit a long description would break. A list message
# allows 4096 characters but a reply-button message only 1024, and the same
# description appears on both prompts, so 1024 is the figure that can never be
# exceeded. The description also carries the "Available pack sizes" line and the
# product name, so the editor reserves room for those.
WA_BODY_LIMIT = 1024
CATALOG_SUMMARY_HEADROOM = 120

WA_LIST_SECTION_TITLE_LIMIT = 24


def _wa_clip(text, limit):
    text = " ".join(str(text or "").split())
    if len(text) <= limit:
        return text
    return text[:limit - 1].rstrip() + "…"


def _wa_text_payload(body):
    return {"type": "text", "text": {"body": body}}


def _wa_button_payload(body, options):
    return {
        "type": "interactive",
        "interactive": {
            "type": "button",
            "body": {"text": body},
            "action": {
                "buttons": [
                    {"type": "reply",
                     "reply": {"id": option["id"],
                               "title": _wa_clip(option["label"], WA_BUTTON_TITLE_LIMIT)}}
                    for option in options[:WA_BUTTON_LIMIT]
                ]
            },
        },
    }


def _wa_list_payload(body, options, nav_count=0, language="en"):
    content = options[:len(options) - nav_count] if nav_count else options
    sections = []
    if content:
        sections.append({
            "title": _shop_translate_text("Choose", language),
            "rows": [{"id": option["id"],
                      "title": _wa_clip(option["label"], WA_LIST_ROW_TITLE_LIMIT)}
                     for option in content],
        })
    if nav_count:
        sections.append({
            "title": _shop_translate_text("Navigation", language),
            "rows": [{"id": option["id"],
                      "title": _wa_clip(option["label"], WA_LIST_ROW_TITLE_LIMIT)}
                     for option in options[len(options) - nav_count:]],
        })
    return {
        "type": "interactive",
        "interactive": {
            "type": "list",
            "body": {"text": body},
            "action": {"button": _shop_translate_text("Choose an option", language),
                       "sections": sections},
        },
    }


def _shop_offer_language(content_count, nav_count, must_list):
    """Whether a Language shortcut can be added without changing the prompt.

    WhatsApp allows three reply buttons and ten list rows, so the shortcut is
    offered only where there is genuinely room for it: never by pushing a prompt
    that fits in buttons into a list, and never by pushing a business choice out
    of the rows and into the numbered text at the bottom instead.
    """
    if not nav_count:
        return False
    if not must_list and content_count + nav_count <= WA_BUTTON_LIMIT:
        return content_count + nav_count + 1 <= WA_BUTTON_LIMIT
    return content_count + nav_count + 1 <= WA_LIST_ROWS_MAX


def shop_whatsapp_payloads(messages, nav=None, language="en"):
    """Render one assistant turn as WhatsApp buttons or a list.

    Buttons are used when the whole prompt fits in three replies, a list when it
    does not. WhatsApp caps a list at ten rows, so any choices beyond that stay
    in the body as numbers — those numbers map to the same choices the engine
    stores, so typing one still works.
    """
    texts = []
    choice = None
    for message in messages or []:
        if not message:
            continue
        if message.get("options"):
            choice = message
        else:
            texts.append(message.get("text") or "")

    parts = [part.strip() for part in texts if part and part.strip()]
    choice_text = (choice.get("text") or "").strip() if choice else ""
    if choice_text:
        parts.append(choice_text)

    content_options = list((choice or {}).get("options") or [])
    # A prompt can insist on a list. The pack size choice does, because a product
    # may offer up to ten sizes and reply buttons stop at three.
    must_list = bool((choice or {}).get("force_list"))
    nav_options = shop_nav_options(nav, language)
    if _shop_offer_language(len(content_options), len(nav_options), must_list):
        nav_options = shop_nav_options(nav, language, with_language=True)
    options = content_options + nav_options
    body = "\n\n".join(parts)

    if not options:
        return [_wa_text_payload(body)] if body else []

    if not must_list and len(options) <= WA_BUTTON_LIMIT:
        prompt = body or _shop_translate_text("Choose an option:", language)
        if len(prompt) > WA_BUTTON_BODY_LIMIT:
            return [_wa_text_payload(prompt), _wa_button_payload(
                _shop_translate_text("Choose an option:", language), options)]
        return [_wa_button_payload(prompt, options)]

    capacity = WA_LIST_ROWS_MAX - len(nav_options)
    if len(content_options) > capacity:
        hidden = content_options[capacity:]
        body = body + "\n\n" + _shop_translate_text("Reply with a number for the rest:", language) + "\n" + "\n".join(
            f"{index}. {option['label']}"
            for index, option in enumerate(hidden, start=capacity + 1))
        options = content_options[:capacity] + nav_options
    return [_wa_list_payload(body, options, len(nav_options), language)]


def shop_messages_to_text(messages, nav=None, language="en"):
    """Flatten assistant messages into WhatsApp-friendly text."""
    parts = []
    for message in messages:
        text = message.get("text", "")
        options = message.get("options") or []
        if options:
            text = f"{text}\n\n" + "\n".join(
                f"{index}. {option['label']}" for index, option in enumerate(options, start=1))
        parts.append(text)
    body = "\n\n".join(part for part in parts if part)
    nav_text = shop_nav_block(nav, language)
    if nav_text:
        body = f"{body}\n\n{nav_text}"
    return body


def shop_option_ids(messages):
    """Choice ids offered by the last prompt — never the navigation shortcuts."""
    for message in reversed(messages):
        options = message.get("options") or []
        if options:
            return [option["id"] for option in options]
    return []


_CUSTOMER_HUMAN_KEYWORDS = (
    "human", "agent", "representative", "talk to someone", "speak to someone",
    "customer care", "talk to a person",
)


def crm_chat_is_muted(wa_number):
    """True when the assistant must stay silent for this conversation.

    Escalated chats and chats taken over by a human agent are both muted: the
    bot never talks over a person.
    """
    try:
        ensure_crm_tables()
        with get_db() as (cursor, connection):
            cursor.execute("SELECT status FROM whatsapp_chats WHERE wa_number = %s",
                           (str(wa_number)[-15:],))
            row = cursor.fetchone()
        return bool(row and row[0] in ("escalated", "human"))
    except Exception as e:
        print(f"CRM mute lookup error: {e}")
        return False


def crm_escalate_chat(wa_number, reason, channel=None, display_name=None):
    """Raise an unattended enquiry for the CRM team and mute the assistant."""
    crm_record_message(wa_number, "inbound", "system", reason, "system",
                       display_name=display_name, company_reg=COMPANY_SYSTEM_PREFIX,
                       escalate=True, reason=reason, channel=channel)
    try:
        ensure_crm_tables()
        with get_db() as (cursor, connection):
            cursor.execute("""
                UPDATE whatsapp_chats
                SET status = 'escalated', unattended = TRUE, handoff_reason = %s, updated_at = NOW()
                WHERE wa_number = %s
            """, (reason, str(wa_number)[-15:]))
            connection.commit()
    except Exception as e:
        print(f"CRM escalate error: {e}")
    _push_alert_unattended(wa_number, reason, display_name)


def _push_alert_unattended(wa_number, reason, display_name=None):
    """Notify subscribed staff devices that a customer needs a person.

    Runs in its own thread so a slow push service never delays the WhatsApp
    webhook, which Meta expects to answer promptly.
    """
    if not push_configured():
        return
    who = (display_name or "").strip() or f"+{str(wa_number)[-15:]}"
    title = f"{who} needs a person"
    body = (reason or "A customer is waiting for a reply").strip()

    def worker():
        try:
            push_notify_staff(title, body[:180], url="/portal/crm")
        except Exception as e:
            print(f"push alert error: {e}")

    threading.Thread(target=worker, daemon=True).start()


def _wa_inbound_preview(message):
    """Return (readable_text, message_type, reply_id) for an inbound message."""
    mtype = message.get("type")
    if mtype == "text":
        text = (message.get("text") or {}).get("body", "")
        return text, "text", text.strip()
    if mtype == "interactive":
        interactive = message.get("interactive") or {}
        kind = interactive.get("type")
        if kind == "button_reply":
            reply = interactive.get("button_reply") or {}
            return reply.get("title", ""), "button", reply.get("id", "")
        if kind == "list_reply":
            reply = interactive.get("list_reply") or {}
            return reply.get("title", ""), "list", reply.get("id", "")
        if kind == "nfm_reply":
            return "Form response", "flow", ""
    labels = {"image": "[image]", "video": "[video]", "audio": "[voice note]",
              "document": "[document]", "sticker": "[sticker]", "location": "[location]",
              "contacts": "[contact]"}
    return labels.get(mtype, f"[{mtype or 'unknown'}]"), mtype or "unknown", ""


def _crm_reply(wa_number, text, channel=None, sender="bot"):
    """Send an assistant reply over WhatsApp and log it either way.

    The transcript is the record of what the customer was told, so the reply is
    stored even when WhatsApp delivery fails; 'delivered' carries the outcome.
    """
    sent, _detail = crm_send_whatsapp(wa_number, text, channel)
    crm_record_message(wa_number, "outbound", sender, text, "text",
                       company_reg=COMPANY_SYSTEM_PREFIX, channel=channel, delivered=sent,
                       sender_name="Assistant" if sender == "bot" else "")
    return sent


_number_mode_ready = False


def ensure_number_mode_table():
    """Create the staff/customer mode table the first time it is needed."""
    global _number_mode_ready
    if _number_mode_ready:
        return
    with get_db() as (cursor, connection):
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS whatsapp_number_modes (
                wa_number VARCHAR(32) PRIMARY KEY,
                mode VARCHAR(20) NOT NULL DEFAULT 'staff',
                updated_at TIMESTAMP DEFAULT NOW()
            );
        """)
        connection.commit()
    _number_mode_ready = True


def wa_mode_get(wa_number):
    """'staff' (the default) or 'customer' for a number that is on the system."""
    try:
        ensure_number_mode_table()
        with get_db() as (cursor, connection):
            cursor.execute("SELECT mode FROM whatsapp_number_modes WHERE wa_number = %s",
                           (str(wa_number)[-15:],))
            row = cursor.fetchone()
        return (row[0] if row and row[0] else "staff")
    except Exception as e:
        print(f"number mode lookup failed: {e}")
        return "staff"


def wa_mode_set(wa_number, mode):
    try:
        ensure_number_mode_table()
        with get_db() as (cursor, connection):
            cursor.execute("""
                INSERT INTO whatsapp_number_modes (wa_number, mode, updated_at)
                VALUES (%s, %s, NOW())
                ON CONFLICT (wa_number) DO UPDATE
                SET mode = EXCLUDED.mode, updated_at = NOW()
            """, (str(wa_number)[-15:], mode))
            connection.commit()
        return True
    except Exception as e:
        print(f"number mode save failed: {e}")
        return False


def shop_webhook_turn(sender_id, display_phone_number, message, staff=False, display_name=None):
    """Run one shopping-assistant turn over WhatsApp.

    Returns the actions still to be handled by the caller. Staff conversations
    are answered and recorded like customer ones, but they are flagged as staff
    so they never count as unattended customer enquiries. The inbound message is
    recorded by the caller, which already knows whether the sender is staff.
    """
    text, mtype, reply_id = _wa_inbound_preview(message)
    staff = bool(staff)
    state_key = f"wa:{str(sender_id)[-15:]}"
    state = shop_load_state(state_key) or {"step": "menu", "cart": [], "ctx": {},
                                          "customer": {}, "history": []}
    state["staff"] = staff
    if display_name:
        state["display_name"] = " ".join(str(display_name).split()).strip()

    new_state, messages, actions = shop_engine(
        state, raw_input=text, button_id=reply_id,
        channel="whatsapp-staff" if staff else "whatsapp", wa_number=sender_id,
        display_name=display_name)
    shop_save_state(state_key, new_state)

    # The switch back to the staff assistant is rendered by the caller.
    if any(action.get("type") == "switch_staff" for action in actions):
        return actions

    shop_send_whatsapp(sender_id, messages, new_state.get("nav"), display_phone_number,
                       staff=staff, language=new_state.get("language", "en"))
    return actions


def shop_send_whatsapp(wa_number, messages, nav, channel=None, staff=False, language="en"):
    """Deliver one assistant turn as WhatsApp buttons/lists, then log it.

    The transcript keeps the full readable prompt — including every choice — so
    an agent reading the conversation sees everything the customer was offered.
    """
    payloads = shop_whatsapp_payloads(messages, nav, language)
    readable = shop_messages_to_text(messages, nav, language)
    if not payloads and not readable:
        return False

    kind = "text"
    ok = True
    for payload in payloads:
        sent, detail = crm_send_whatsapp_payload(wa_number, payload, channel)
        if payload.get("type") == "interactive":
            kind = (payload.get("interactive") or {}).get("type") or "interactive"
            if not sent:
                # Never leave a customer without a reply: if WhatsApp rejects the
                # rich message, send the same prompt as plain text.
                print(f"interactive send failed, falling back to text: {detail}")
                retry, retry_detail = crm_send_whatsapp(wa_number, readable or "", channel)
                if retry:
                    kind = "text"
                    sent = True
                else:
                    print(f"text fallback failed: {retry_detail}")
        ok = ok and sent

    if readable:
        crm_record_message(wa_number, "outbound", "staff" if staff else "bot", readable,
                           kind, company_reg=COMPANY_SYSTEM_PREFIX, channel=channel,
                           delivered=ok, is_staff=staff,
                           sender_name="Assistant" if not staff else "")
    return ok


def crm_customer_webhook(sender_id, display_phone_number, message, profile_name=""):
    """Run the shopping assistant for a customer (a number that is not staff)."""
    ensure_company_system_tables()
    text, mtype, reply_id = _wa_inbound_preview(message)
    lowered = (text or "").strip().lower()
    wants_human = any(keyword in lowered for keyword in _CUSTOMER_HUMAN_KEYWORDS)

    crm_record_message(sender_id, "inbound", "customer", text or f"[{mtype}]", mtype,
                       display_name=(profile_name or "").strip() or None,
                       company_reg=COMPANY_SYSTEM_PREFIX, channel=display_phone_number)

    # An agent already owns this conversation — stay quiet and let them answer.
    if crm_chat_is_muted(sender_id):
        if wants_human:
            crm_escalate_chat(sender_id, "Customer requested a human agent", display_phone_number)
        return

    if wants_human:
        _crm_reply(sender_id, "Of course — I am connecting you with a member of our sales team. "
                              "Someone will reply here shortly. 🙏", display_phone_number)
        crm_escalate_chat(sender_id, "Customer requested a human agent", display_phone_number)
        return

    actions = shop_webhook_turn(sender_id, display_phone_number, message, staff=False,
                               display_name=(profile_name or "").strip() or None)
    for action in actions:
        if action.get("type") == "escalate":
            crm_escalate_chat(sender_id, action.get("reason") or "Customer enquiry",
                              display_phone_number)


def _safe_scalar(query, params=None, default=0):
    try:
        with get_db() as (cursor, connection):
            cursor.execute(query, params or ())
            row = cursor.fetchone()
            return row[0] if row and row[0] is not None else default
    except Exception as e:
        print(f"count query failed: {e}")
        return default


# ------------------------------------------------------------- display times --
# Timestamps are written by PostgreSQL's NOW() into naive TIMESTAMP columns and
# the database runs in UTC, so a value read back is UTC with no tzinfo attached.
# Formatting it directly shows UTC, which reads as two hours behind in Zimbabwe.
DISPLAY_TZ_OFFSET = int(os.getenv("DISPLAY_TZ_OFFSET", "2"))


def local_time(value):
    """A stored UTC timestamp as local time, or None."""
    if value is None:
        return None
    if value.tzinfo is not None:
        value = value.astimezone(timezone.utc).replace(tzinfo=None)
    return value + timedelta(hours=DISPLAY_TZ_OFFSET)


def fmt_time(value, pattern="%d %b %Y %H:%M"):
    """A stored UTC timestamp formatted for display in local time."""
    local = local_time(value)
    return local.strftime(pattern) if local else ""


