# Every action a staff member can take that is worth recording. Keeping the
# labels here means the portal and the log can never drift apart.
AUDIT_CATEGORIES = {
    "auth": "Sign in",
    "catalogue": "Products & pricing",
    "chat": "Conversations",
    "order": "Orders",
    "access": "User access",
    "hr": "HR & Payroll",
}


def log_activity(action, category, summary, target=None, details=None, user=None):
    """Record one staff action for the CRM activity log.

    Never raises: an audit failure must not break the action being audited.
    """
    if category not in AUDIT_CATEGORIES:
        category = "auth"
    try:
        ensure_audit_tables()
        user = user or {}
        employee_name = (user.get('name')
                         or f"{user.get('firstname', '')} {user.get('surname', '')}".strip()
                         or 'Unknown')
        try:
            ip_address = (request.headers.get('X-Forwarded-For', '').split(',')[0].strip()
                          or request.remote_addr or '')
        except Exception:
            ip_address = ''
        with get_db() as (cursor, connection):
            cursor.execute("""
                INSERT INTO company_activity_log (employee_id, employee_name, employee_role,
                                                  employee_email, action, category, summary,
                                                  target, details, ip_address, created_at)
                VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, NOW())
            """, (user.get('id'), employee_name, user.get('role'), user.get('email'),
                  str(action)[:60], category, str(summary or '')[:1000],
                  (str(target)[:200] if target else None),
                  (json.dumps(details)[:4000] if details is not None else None),
                  ip_address[:64]))
            connection.commit()
        return True
    except Exception as e:
        print(f"activity log error: {e}")
        return False


def ensure_company_system_tables():
    """Create every company system table.

    Read paths need this as much as write paths: the CRM inbox, the access
    matrix and the order log all query tables that may not exist yet on a fresh
    deployment or in a worker that has not written anything. Each helper is
    guarded so one failure cannot stop the others from being attempted, and a
    successful run is remembered for the lifetime of the process.
    """
    for ensure in (ensure_crm_tables, ensure_shop_tables, ensure_access_tables,
                   ensure_audit_tables, ensure_number_mode_table):
        try:
            ensure()
        except Exception as e:
            print(f"table setup failed ({ensure.__name__}): {e}")


def default_module_access(role):
    """Administrators get every portal; everyone else starts with leave only."""
    if str(role or '') == COMPANY_SYSTEM_ADMIN_ROLE:
        return {key: True for key in COMPANY_MODULE_KEYS}
    return {key: key == "leave" for key in COMPANY_MODULE_KEYS}


def employee_module_access(employee_id, role):
    """Portal access for one employee: defaults overridden by stored toggles."""
    access = default_module_access(role)
    if employee_id is None:
        return access
    try:
        ensure_access_tables()
        with get_db() as (cursor, connection):
            cursor.execute("SELECT module, enabled FROM company_module_access WHERE employee_id = %s",
                           (int(employee_id),))
            for module, enabled in cursor.fetchall():
                if module in access:
                    access[module] = bool(enabled)
    except Exception as e:
        print(f"module access lookup failed: {e}")
    return access


def user_modules(user):
    """Portal definitions the signed-in user is allowed to open."""
    access = (user or {}).get("modules") or {}
    return [module for module in COMPANY_MODULES if access.get(module["key"])]


def set_module_access(employee_id, module, enabled, updated_by=None):
    if module not in COMPANY_MODULE_KEYS:
        return False
    try:
        ensure_access_tables()
        with get_db() as (cursor, connection):
            cursor.execute("""
                INSERT INTO company_module_access (employee_id, module, enabled, updated_by, updated_at)
                VALUES (%s, %s, %s, %s, NOW())
                ON CONFLICT (employee_id, module) DO UPDATE
                SET enabled = EXCLUDED.enabled,
                    updated_by = EXCLUDED.updated_by,
                    updated_at = NOW()
            """, (int(employee_id), module, bool(enabled), updated_by))
            connection.commit()
        return True
    except Exception as e:
        print(f"module access update failed: {e}")
        return False


def access_matrix():
    """Every employee with their effective portal access flags."""
    ensure_company_system_tables()
    with get_db() as (cursor, connection):
        cursor.execute(f"""
            SELECT id, firstname, surname, role, department
            FROM {COMPANY_SYSTEM_TABLE}
            ORDER BY firstname, surname
        """)
        employees = cursor.fetchall()
        cursor.execute("SELECT employee_id, module, enabled FROM company_module_access")
        overrides = {}
        for employee_id, module, enabled in cursor.fetchall():
            overrides.setdefault(employee_id, {})[module] = bool(enabled)

    matrix = []
    for employee_id, firstname, surname, role, department in employees:
        access = default_module_access(role)
        access.update(overrides.get(employee_id, {}))
        matrix.append({
            "id": employee_id,
            "name": f"{firstname or ''} {surname or ''}".strip() or f"Employee {employee_id}",
            "role": role or "",
            "department": department or "",
            "modules": access,
        })
    return matrix


def company_system_user():
    """Return the signed-in company system user with portal access, or None."""
    if not session.get("company_system"):
        return None
    firstname = session.get("cs_firstname") or ""
    surname = session.get("cs_surname") or ""
    role = session.get("cs_role", "")
    return {
        "id": session.get("empid"),
        "firstname": firstname,
        "surname": surname,
        "role": role,
        "email": session.get("cs_email", ""),
        "initials": (firstname[:1] + surname[:1]).upper() or "BC",
        "company_name": COMPANY_SYSTEM_NAME,
        "modules": employee_module_access(session.get("empid"), role),
    }


def company_system_guard(module=None):
    """Return (user, None) when allowed, otherwise (None, redirect response)."""
    user = company_system_user()
    if not user:
        return None, redirect(url_for('company_login_page'))
    if module and not user["modules"].get(module):
        return None, redirect(url_for('company_system', denied=module))
    return user, None


def portal_api_user(module=None):
    """Return (user, None) when allowed, otherwise (None, JSON error response)."""
    user = company_system_user()
    if not user:
        return None, (jsonify({'success': False, 'message': 'Unauthorized'}), 401)
    if module and not user["modules"].get(module):
        return None, (jsonify({'success': False, 'message': 'You cannot open this portal.'}), 403)
    return user, None


def company_system_stats():
    """Headline numbers shown on the portal hub cards.

    The counts are combined into one statement because the database is remote,
    so the cost of this function is the number of round trips rather than the
    amount of work: six separate counts cost six round trips for the same data.
    """
    ensure_company_system_tables()
    pending_table = f"{COMPANY_SYSTEM_PREFIX}appspendingapproval"
    stats = {
        "stat_employees": 0,
        "stat_pending_leave": 0,
        "stat_roles": 0,
        "stat_unattended": 0,
        "stat_open_chats": 0,
        "stat_human_chats": 0,
    }
    try:
        with get_db() as (cursor, connection):
            cursor.execute(f"""
                SELECT
                    (SELECT COUNT(*) FROM {COMPANY_SYSTEM_TABLE}),
                    (SELECT COUNT(*) FROM {pending_table}),
                    (SELECT COUNT(DISTINCT role) FROM {COMPANY_SYSTEM_TABLE}),
                    (SELECT COUNT(*) FROM whatsapp_chats
                      WHERE company_reg = %s AND unattended = TRUE AND status <> 'closed'),
                    (SELECT COUNT(*) FROM whatsapp_chats
                      WHERE company_reg = %s AND status <> 'closed'),
                    (SELECT COUNT(*) FROM whatsapp_chats
                      WHERE company_reg = %s AND status = 'human')
            """, (COMPANY_SYSTEM_PREFIX, COMPANY_SYSTEM_PREFIX, COMPANY_SYSTEM_PREFIX))
            row = cursor.fetchone()
        if row:
            for key, value in zip(stats, row):
                stats[key] = value or 0
    except Exception as e:
        print(f"portal stats query failed: {e}")
    return stats


def _crm_chats(filter_key="all", search=None):
    """Conversations for the CRM inbox.

    `search` matches the customer's name, their WhatsApp number, or the text of
    any message in the conversation — so an agent can find a chat by the product
    a customer asked about, not just by who they are or what they last said.
    """
    ensure_company_system_tables()
    where = ["company_reg = %s"]
    params = [COMPANY_SYSTEM_PREFIX]
    if filter_key == "unattended":
        where.append("unattended = TRUE AND status <> 'closed'")
    elif filter_key == "human":
        where.append("status = 'human'")
    elif filter_key == "bot":
        where.append("status = 'bot'")
    elif filter_key == "closed":
        where.append("status = 'closed'")
    elif filter_key == "staff":
        where.append("is_staff = TRUE")
    elif filter_key == "customers":
        where.append("is_staff = FALSE")
    else:
        where.append("status <> 'closed'")

    search = " ".join(str(search or "").split()).strip()
    if search:
        like = f"%{search}%"
        digits = "".join(character for character in search if character.isdigit())
        # Match the customer's name, their number, or any message in the chat.
        clauses = ["display_name ILIKE %s", "wa_profile_name ILIKE %s"]
        params.append(like)
        params.append(like)
        if digits:
            clauses.append("wa_number LIKE %s")
            params.append(f"%{digits}%")
        clauses.append("EXISTS (SELECT 1 FROM whatsapp_messages messages "
                       "WHERE messages.chat_id = chats.id AND messages.body ILIKE %s)")
        params.append(like)
        where.append("(" + " OR ".join(clauses) + ")")

    query = f"""
        SELECT id, wa_number, display_name, status, unattended, handoff_reason,
               unread_count, last_message, last_message_at, assigned_to, is_staff,
               COALESCE(wa_profile_name, display_name)
        FROM whatsapp_chats chats
        WHERE {' AND '.join(where)}
        ORDER BY COALESCE(last_message_at, created_at) DESC
        LIMIT 100
    """
    with get_db() as (cursor, connection):
        cursor.execute(query, tuple(params))
        rows = cursor.fetchall()
        badges = _crm_chat_badges([row[1] for row in rows] if rows else [])
    chats = []
    for row in rows:
        chats.append({
            "id": row[0],
            "wa_number": row[1],
            "display_name": row[2] or f"+{row[1]}",
            "status": row[3],
            "unattended": bool(row[4]),
            "handoff_reason": row[5],
            "unread_count": row[6] or 0,
            "last_message": row[7],
            "last_message_at": fmt_time(row[8], "%d %b %Y %H:%M"),
            "last_message_iso": local_time(row[8]).isoformat() if row[8] else "",
            "assigned_to": row[9] or "",
            "is_staff": bool(row[10]),
            "kind": "inhouse" if row[10] else "shopping",
            "badges": badges.get(str(row[1]), []),
        })
    return chats


def _crm_chat_badges(wa_numbers):
    """Sales context per chat, for the tags shown on each inbox card.

    Reports whether the customer has placed an order, whether any of it is paid
    (and via EcoCash specifically), and whether the last send to them bounced off
    WhatsApp's 24-hour window. Keyed by wa_number.
    """
    context = {}
    numbers = [str(number)[-15:] for number in wa_numbers or [] if number]
    if not numbers:
        return context
    for number in numbers:
        context[number] = []
    try:
        with get_db() as (cursor, connection):
            cursor.execute("""
                SELECT wa_number, COUNT(*),
                       SUM(CASE WHEN payment_status = 'paid' THEN 1 ELSE 0 END),
                       SUM(CASE WHEN payment_status = 'paid'
                                 AND COALESCE(payment_method, '') ILIKE '%%ecocash%%'
                                THEN 1 ELSE 0 END)
                FROM shop_orders
                WHERE wa_number = ANY(%s)
                GROUP BY wa_number
            """, (numbers,))
            for row in cursor.fetchall():
                key = str(row[0])[-15:]
                tags = context.setdefault(key, [])
                if row[1]:
                    tags.append({"label": f"{row[1]} order(s)" if row[1] > 1 else "Order placed",
                                 "tone": "order"})
                if row[3]:
                    tags.append({"label": "Paid via EcoCash", "tone": "paid"})
                elif row[2]:
                    tags.append({"label": "Paid", "tone": "paid"})

            cursor.execute("""
                SELECT chats.wa_number, messages.delivered
                FROM whatsapp_chats chats
                LEFT JOIN LATERAL (
                    SELECT delivered FROM whatsapp_messages
                    WHERE chat_id = chats.id AND direction = 'outbound'
                    ORDER BY id DESC LIMIT 1
                ) messages ON TRUE
                WHERE chats.wa_number = ANY(%s)
            """, (numbers,))
            for row in cursor.fetchall():
                if row[1] is False:
                    context.setdefault(str(row[0])[-15:], []).append(
                        {"label": "Outside 24h window", "tone": "window"})
    except Exception as e:
        print(f"CRM badge lookup error: {e}")
    return context


@app.route('/company-login', methods=['GET', 'POST'])
def company_login_page():
    if request.method == 'POST':
        email = (request.form.get('email') or '').strip()
        password = (request.form.get('password') or '').strip()

        if not email or not password:
            return jsonify({'success': False, 'message': 'Email and password are required.'}), 400

        try:
            with get_db() as (cursor, connection):
                cursor.execute(f"SELECT * FROM {COMPANY_SYSTEM_TABLE} WHERE email = %s", (email,))
                row = cursor.fetchone()

            if not row:
                return jsonify({'success': False, 'message': 'This email is not registered with the company system.'}), 404

            if str(row[6]) != password:
                return jsonify({'success': False, 'message': 'Incorrect password.'}), 401

            role = str(row[8] or '')
            access = employee_module_access(int(row[0]), role)
            if not any(access.values()):
                return jsonify({
                    'success': False,
                    'message': 'Your account does not have access to any company system portal yet. '
                               'Please contact your company administrator.'
                }), 403

            session.clear()
            session.permanent = True
            session['user_uuid'] = str(uuid.uuid4())
            session['table_name'] = COMPANY_SYSTEM_TABLE
            session['empid'] = int(row[0])
            session['company_system'] = True
            session['cs_firstname'] = row[1]
            session['cs_surname'] = row[2]
            session['cs_role'] = role
            session['cs_email'] = email
            user_sessions[email] = {'uuid': session['user_uuid'], 'email': email}

            log_activity("signed_in", "auth",
                         f"{row[1]} {row[2]} signed in".strip(),
                         target=email,
                         details={"role": role,
                                  "portals": sorted(k for k, v in access.items() if v)},
                         user={"id": int(row[0]), "firstname": row[1], "surname": row[2],
                               "role": role, "email": email})

            return jsonify({'success': True, 'redirect': url_for('company_system')})

        except Exception as e:
            print(f"Company login error: {e}")
            return jsonify({'success': False, 'message': 'Unable to sign in right now. Please try again.'}), 500

    if company_system_user():
        return redirect(url_for('company_system'))
    return render_template('company_login.html', company_name=COMPANY_SYSTEM_NAME,
                           channel_number=company_system_channel_label())


@app.route('/company-logout')
def company_logout():
    user = company_system_user()
    if user:
        log_activity("signed_out", "auth",
                     f"{user.get('firstname', '')} {user.get('surname', '')}".strip() + " signed out",
                     target=user.get('email', ''),
                     user={"id": user.get('id'), "name": user.get('name'),
                           "role": user.get('role'), "email": user.get('email')})
    session.clear()
    return redirect(url_for('company_login_page'))


